class FileEntry:
    def __init__(self, path):
        # Normalizar separadores (str(Path(...)) usa "\" en Windows) — sin
        # esto, la MISMA ruta con "/" y con "\" se trata como dos archivos
        # distintos en cualquier comparación por igualdad de texto (duplica
        # filas al detectar el mismo archivo dos veces, y hace fallar la
        # búsqueda en auto_processed.json, cuyas claves siempre usan "\").
        self.path         = str(Path(path))
        self.name         = Path(path).name
        self.ext          = get_extension(path)
        self.is_book      = is_book_file(self.path)
        self.is_comic     = is_comic_file(self.path)
        # folder_hint: apoyo para series/mangas cuyos archivos vienen
        # numerados a secas ("01.cbr") y el nombre real está en la carpeta
        # que los contiene -- ver core/api_client.py::detect_episode. Solo
        # se usa si el propio nombre de archivo no deja título aprovechable.
        self.detected     = detect_episode(self.name, is_book=self.is_book, is_comic=self.is_comic,
                                            folder_hint=Path(self.path).parent.name)
        self.media_info   = None
        self.new_name     = ""
        self.status       = "pendiente"
        self.error_msg    = ""
        self.ftp_progress = 0.0
        self.ftp_speed    = 0.0
        self.ftp_status   = ""
        self.confidence   = 0   # 0-100 porcentaje de confianza en la detección TMDB
        self.remote_dir_override = None   # carpeta remota elegida a mano, sustituye a la calculada por categoría/género
        self._last_known_size_text = ""   # ver App._file_size_text -- último tamaño leído con éxito
        self._last_known_size_bytes = None   # ver App._update_status_bar -- caché para no re-stat()ear todo self.files en cada fila actualizada

    def to_dict(self) -> dict:
        status = self.status
        # Persistir progreso de subida a medias para que al reabrir la app
        # la barra no fluctúe 0%→45%→0% (ver issue barra fluctuante). Antes se
        # demotaba subiendo/en_cola→pendiente y se perdía ftp_progress, así que
        # _begin_ftp_upload reseteaba a 0% y el resume a 45% alternaba cada 2 s
        # con los "Reintento…" que reaplicaban el 0% guardado.
        ftp_progress = float(getattr(self, "ftp_progress", 0.0) or 0.0)
        if status in ("buscando", "auto"):
            status = "pendiente"
        elif status in ("subiendo", "en_cola"):
            # Conservar como en_cola con progreso para que al reiniciar se vea
            # "En cola 45%" y no "pendiente 0%" y el siguiente upload no
            # parpadee. El usuario puede re-lanzar sin duplicar.
            status = "en_cola"
        return {
            "path":       self.path,
            "new_name":   self.new_name,
            "status":     status,
            "confidence": self.confidence,
            "media_info": _mediainfo_to_dict(self.media_info) if self.media_info else None,
            "remote_dir_override": self.remote_dir_override,
            # Solo relevante para libros/cómics (self.is_book) -- persiste
            # la elección manual de _set_book_comic_type, que si no se
            # perdería al reiniciar la app (from_dict() recalcularía is_comic
            # solo por extensión, como al añadir el archivo por primera vez).
            "is_comic": self.is_comic,
            # Ver App._file_size_text -- sin esto, un archivo ya procesado
            # (movido a "procesados/" o borrado tras subir, según "Acción
            # tras subir") se queda con la columna "Peso" en blanco justo
            # tras reiniciar la app: entry.path ya no existe en disco, y
            # sin el último tamaño conocido guardado aquí no hay nada que
            # mostrar en su lugar (el caché en memoria no sobrevive un
            # reinicio si no se persiste).
            "last_known_size_bytes": self._last_known_size_bytes,
            "ftp_progress": ftp_progress,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "FileEntry":
        entry = cls(d["path"])
        entry.new_name   = d.get("new_name", "")
        entry.status     = d.get("status", "pendiente")
        entry.confidence = d.get("confidence", 0)
        entry.remote_dir_override = d.get("remote_dir_override")
        # Restaura la elección manual de _set_book_comic_type si difiere de
        # la que ya sale por extensión (is_comic_file en core/renamer.py) --
        # hay que recalcular entry.detected también, porque se calculó en
        # cls(d["path"]) con el is_comic por defecto, no con el guardado.
        saved_is_comic = d.get("is_comic")
        if entry.is_book and saved_is_comic is not None and saved_is_comic != entry.is_comic:
            entry.is_comic = saved_is_comic
            entry.detected = detect_episode(entry.name, is_book=entry.is_book, is_comic=entry.is_comic,
                                             folder_hint=Path(entry.path).parent.name)
        entry._last_known_size_bytes = d.get("last_known_size_bytes")
        if entry._last_known_size_bytes is not None:
            entry._last_known_size_text = _fmt_size(entry._last_known_size_bytes)
        # Restaurar progreso de subida previa (ver to_dict: evita fluctuación 0%↔45%)
        try:
            entry.ftp_progress = float(d.get("ftp_progress", 0.0) or 0.0)
        except Exception:
            entry.ftp_progress = 0.0
        entry.ftp_progress = max(0.0, min(1.0, entry.ftp_progress))
        if entry.status == "en_cola" and entry.ftp_progress > 0:
            entry.ftp_status = f"{entry.ftp_progress*100:.0f}% (pendiente de reanudar)"
        mi = d.get("media_info")
        if mi:
            from core.api_client import MediaInfo
            entry.media_info = MediaInfo(
                tmdb_id        = mi.get("tmdb_id", 0),
                media_type     = mi.get("media_type", "tv"),
                title          = mi.get("title", ""),
                original_title = mi.get("original_title", ""),
                year           = mi.get("year", ""),
                poster_url     = mi.get("poster_url"),
                season         = mi.get("season"),
                episode        = mi.get("episode"),
                episode_title  = mi.get("episode_title"),
                overview       = mi.get("overview", ""),
                genre_ids      = mi.get("genre_ids", []),
            )
        return entry


_STATUS_RANK = {
    "subido": 5, "renombrado": 4, "listo": 3, "en_cola": 3, "subiendo": 3,
    "auto": 2, "omitido": 1, "error": 1, "pendiente": 0, "buscando": 0,
}


def _dedupe_entries(entries: list) -> list:
    """Colapsa entradas con el mismo entry.path (normalizado) en una sola —
    puede haber duplicados en session.json de antes de normalizar
    separadores de ruta (la misma ruta con "/" y con "\\" se guardaba como
    dos archivos distintos). Se queda con la de estado más avanzado; en
    empate, con la que tenga media_info."""
    best = {}
    order = []
    for e in entries:
        if e.path not in best:
            best[e.path] = e
            order.append(e.path)
            continue
        cur = best[e.path]
        rank_new = _STATUS_RANK.get(e.status, 0)
        rank_cur = _STATUS_RANK.get(cur.status, 0)
        if rank_new > rank_cur or (rank_new == rank_cur and e.media_info and not cur.media_info):
            best[e.path] = e
    return [best[k] for k in order]


def _mediainfo_to_dict(info) -> dict:
    return {
        "tmdb_id":        info.tmdb_id,
        "media_type":     info.media_type,
        "title":          info.title,
        "original_title": info.original_title,
        "year":           info.year,
        "poster_url":     info.poster_url,
        "season":         info.season,
        "episode":        info.episode,
        "episode_title":  info.episode_title,
        "overview":       info.overview,
        "genre_ids":      info.genre_ids,
    }


def _appdata_dir() -> Path:
    return app_data_dir()


if _DND_AVAILABLE:
    _AppBase = type("_AppBase", (ctk.CTk, TkinterDnD.DnDWrapper), {})
else:
    _AppBase = ctk.CTk


class App(_AppBase):
    def _new_ftp_client(self):
        """Una conexión nueva, del protocolo que esté configurado.

        Todo el que necesite una conexión propia (las subidas en paralelo, las
        estadísticas, liberar espacio...) la pide por aquí y no construyendo
        FTPClient directamente: así cambiar entre FTP y SFTP es un ajuste y no
        una búsqueda por medio archivo. Ver core/transfer.py."""
        from core.transfer import make_client
        return make_client(self.config_data.get("ftp_protocol", "ftp"))

    def __init__(self):
        # Instrumentación temporal de arranque -- para localizar qué fase
        # concreta tarda, en vez de seguir adivinando (ver _t: usado en
        # todo __init__). Quitar cuando se identifique y resuelva la
        # causa real de la lentitud.
        _t0 = _time.perf_counter()
        _t_last = [_t0]

        def _mark(label):
            now = _time.perf_counter()
            _log.info("Arranque: %-40s %6.0f ms (total %6.0f ms)",
                      label, (now - _t_last[0]) * 1000, (now - _t0) * 1000)
            _t_last[0] = now

        super().__init__()
        _mark("super().__init__()")
        # Activar drag & drop si tkinterdnd2 esta disponible
        if _DND_AVAILABLE:
            self.TkdndVersion = TkinterDnD._require(self)
        _mark("TkinterDnD._require")
        self.config_data = Config()
        _mark("Config()")
        self.tmdb = TMDBClient(self.config_data["tmdb_api_key"])
        # Identificación de libros/cómics (ver core/book_client.py,
        # core/comicvine_client.py, core/openlibrary_client.py) -- mismo
        # patrón que self.tmdb. OpenLibrary es el proveedor PRINCIPAL para
        # libros de texto (sin API Key nunca, y más fiable que Google Books
        # desde que su backend empezó a fallar de forma intermitente y
        # persistente) -- Google Books queda como apoyo automático (ver
        # core/book_identify.py). google_books_api_key sigue siendo opcional,
        # igual que comicvine_api_key.
        self.book_client = GoogleBooksClient(self.config_data.get("google_books_api_key", ""))
        self.comicvine = ComicVineClient(self.config_data.get("comicvine_api_key", ""))
        self.openlibrary_client = OpenLibraryClient()
        # Alternativas a ComicVine para manga (catálogo mayoritariamente
        # occidental/inglés, falla a menudo con manga incluso con la
        # traducción vía IA) -- ninguna necesita API Key. Solo se usan
        # cuando el selector manual del panel de búsqueda (ver
        # self._search_provider_override) las elige explícitamente; la
        # identificación automática al añadir archivos sigue igual.
        self.mangadex_client = MangaDexClient()
        self.anilist_client   = AniListClient()
        self.kitsu_client     = KitsuClient()
        self.ftp  = self._new_ftp_client()
        # self.ftp es una única conexión de control compartida con AutoWatcher
        # (ver _toggle_auto) y con varias comprobaciones de fondo de la propia
        # GUI (espacio libre, precarga de carpetas, "Probar conexión", cruce
        # FTP del detector de huecos) -- ftplib no es seguro entre hilos, así
        # que TODAS ellas deben serializarse con este mismo candado, no cada
        # una con el suyo (AutoWatcher tenía uno propio que no protegía nada
        # fuera de sí mismo -- visto de verdad: "550 Failed to change
        # directory" y "200 Switching to Binary mode" tratados como error,
        # ambos síntomas clásicos de respuestas cruzadas entre hilos en la
        # misma conexión).
        self._ftp_cmd_lock = threading.Lock()
        _mark("TMDBClient/FTPClient")
        from core.favorites import load_local_cache
        self._favorites = load_local_cache()
        from core.reservations import load_local_cache as _load_reservations_cache
        self._reservations = _load_reservations_cache()
        self.files = []
        self._selected_entry = None
        # Selección múltiple con Ctrl/Shift+clic (ver _on_row_click) --
        # entradas ADICIONALES al ancla (self._selected_entry, que sigue
        # siendo la única que alimenta el panel de detalles/búsqueda). Usado
        # por "Asignar a la selección" para aplicar el mismo resultado a
        # varios archivos a la vez, cada uno con su propio episodio/número
        # ya detectado (ver _assign_to_selection_worker).
        self._multi_selected = set()

        self._upload_queue          = []
        self._upload_cancel         = threading.Event()
        self._upload_skip           = threading.Event()
        self._upload_running        = False
        self._upload_current_idx    = -1
        self._upload_current_remote = ""
        self._upload_overwrite_all  = False
        self._upload_duplicate_ignore_all = False
        self._rename_overwrite_all  = False
        self._upload_slot_of        = {}
        self._upload_skip_events    = []
        # Serializa las confirmaciones de sobrescribir/duplicado/atascado
        # entre los workers de subida en paralelo: sin esto, cada worker que
        # encontrara un archivo existente abría SU diálogo a la vez (todos
        # veían _upload_overwrite_all=False antes de que ninguno contestara)
        # y contestar "Sobrescribir todos" al primero no evitaba que los
        # demás repitieran la pregunta. Con el lock, solo un worker pregunta
        # a la vez; al contestar "todos", los que esperan el lock ven el flag
        # ya activo y saltan directo a sobrescribir (ver _upload_entry_with).
        self._upload_confirm_lock  = threading.Lock()

        # Reutilización de carpetas de serie ya existentes en el FTP (evita
        # crear una carpeta duplicada por idioma/nombre corto distinto)
        self._series_folder_cache = {}
        self._ftp_dir_cache       = {}
        self._series_folder_lock  = threading.Lock()

        self._watcher: AutoWatcher = None
        self._tray        = None
        self._tray_running = False
        # Notificaciones de "Subida completada" agrupadas -- ver
        # _queue_upload_notification/_flush_upload_notifications.
        self._pending_upload_notifications: list = []
        self._upload_notification_after_id = None
        self._status_bar_debounce_id = None   # ver _ftp_row_live
        self._upload_history: list = []   # historial de subidas en memoria
        self._history_lock = threading.Lock()   # evita carreras al escribir upload_history.json
        # Las operaciones EC de aMule deben serializarse: aMule solo atiende
        # UNA conexión/búsqueda EC a la vez y una nueva conexión cierra a la
        # anterior. Sin este lock, pulsar los botones ⬇ de varios episodios
        # seguidos hacía que solo se descargara el último (cada botón abría
        # su EcClient y mataba la conexión del anterior). Ver
        # _auto_download_episode_on_amule / _downloads_ensure_session.
        self._amule_ec_lock = threading.Lock()
        # Mientras la pestaña Descargas tiene una BÚSQUEDA abierta, la conexión
        # EC en curso es la única que aMule admite: las descargas que el usuario
        # pida durante la búsqueda se envían por ESA misma conexión entre
        # sondeos, sin esperar a que la búsqueda termine (ver
        # _downloads_perform_search / _downloads_do_download_worker). Este
        # lock protege la cola de descargas pendientes y el flag.
        self._downloads_jobs_lock = threading.Lock()
        self._downloads_pending_jobs = []
        self._downloads_search_active = False
        self._downloads_wake = threading.Event()
        # Cupo de subidas simultáneas COMPARTIDO entre la cola manual y el modo
        # automático — "Subidas simultáneas" en Ajustes limita el total real,
        # no cada origen por separado (ver core/upload_slots.py).
        self._upload_slots = UploadSlotManager(self.config_data)
        # Velocidad total de la barra de estado, suavizada (ver
        # _update_status_bar). Constante más corta que la de cada archivo: aquí
        # solo hay que limar el desacompasamiento entre ellos.
        self._total_speed_media = SpeedEWMA(tau=1.0)

        ctk.set_appearance_mode(self.config_data.get("appearance", "dark"))
        ctk.set_default_color_theme(self.config_data.get("color_theme", "blue"))

        self.title(f"aIBechos v{__version__}")
        self.geometry("1200x820")
        self.minsize(1000, 680)
        self._apply_window_state()

        self._icon_path  = None   # .ico — solo Windows, vía iconbitmap()
        self._icon_photo = None   # PNG — macOS/Linux, vía iconphoto(); hay
                                   # que mantener la referencia viva o Tk la
                                   # recolecta y el icono desaparece
        self._icon_png_path = None   # PNG en disco — usado por _get_tray_image()
                                      # en macOS/Linux, donde self._icon_path
                                      # (el .ico) no existe
        try:
            if getattr(sys, "frozen", False):
                base = sys._MEIPASS
            else:
                base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            if is_windows():
                # Tk en macOS/Linux no soporta .ico vía iconbitmap.
                ico = os.path.join(base, "iconoPrincipal.ico")
                if os.path.exists(ico):
                    self._icon_path = ico
            else:
                png = os.path.join(base, "IconoSinFondo.png")
                if os.path.exists(png):
                    self._icon_png_path = png
                    self._icon_photo = ImageTk.PhotoImage(Image.open(png))
        except Exception:
            pass
        self._apply_icon(self)
        if self._icon_path or self._icon_photo:
            # CTk puede resetear el icono; re-aplicar tras el primer frame
            self.after(50, lambda: self._apply_icon(self))
        _mark("icono")

        # Logos de Plex/Jellyfin -- para distinguir de un vistazo, en la
        # fila de cada serie de "Episodios que faltan", de qué servidor
        # viene esa información (antes eran los emoji 📺/🎬, sin relación
        # visual con ninguno de los dos servicios). CTkImage escala él
        # solo según el "widget scaling" activo, así que basta con darle
        # el tamaño final deseado (ver origin_source_icon_size más abajo).
        self._plex_logo_img = None
        self._jellyfin_logo_img = None
        try:
            base = sys._MEIPASS if getattr(sys, "frozen", False) else \
                os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            plex_png = os.path.join(base, "plex_logo.png")
            jellyfin_png = os.path.join(base, "jellyfin_logo.png")
            if os.path.exists(plex_png):
                self._plex_logo_img = ctk.CTkImage(Image.open(plex_png), size=(18, 18))
            if os.path.exists(jellyfin_png):
                self._jellyfin_logo_img = ctk.CTkImage(Image.open(jellyfin_png), size=(18, 18))
        except Exception:
            pass
        # Placeholder transparente real para la columna "logo" de Archivos
        # cuando ni Jellyfin ni Plex están configurados -- CTkLabel con
        # image=None mostraba un glifo inesperado en vez de quedar en
        # blanco (bug real, visto en una captura del usuario). Una imagen
        # de verdad (aunque sea 100% transparente) evita depender de ese
        # camino sin imagen de customtkinter.
        self._blank_logo_img = ctk.CTkImage(Image.new("RGBA", (18, 18), (0, 0, 0, 0)), size=(18, 18))

        self._startup_mark = _mark   # usado dentro de _build_ui, ver ahí
        self._build_ui()
        del self._startup_mark
        _mark("_build_ui() TOTAL")
        self.protocol("WM_DELETE_WINDOW", self._on_close)
        if is_macos():
            # Cmd+Q (y "Salir de aIBechos" del menú de la app en la barra
            # superior del sistema) los gestiona Tk directamente en macOS,
            # sin pasar por WM_DELETE_WINDOW — sin este remapeo, se saltaría
            # el diálogo de "hay una subida en curso" y el guardado de
            # sesión/config de _on_close, cerrando la app en seco.
            try:
                self.createcommand('tk::mac::Quit', self._on_close)
            except Exception:
                pass
            try:
                # Clic en el icono del Dock con la ventana oculta (tras
                # minimizar a bandeja): sin esto, la app se queda sin
                # ventana visible y sin forma obvia de recuperarla salvo
                # encontrar el icono en la barra de menú.
                self.createcommand('tk::mac::ReopenApplication', self._tray_show)
            except Exception:
                pass
        # La bandeja de sistema se crea de forma diferida en
        # _minimize_to_tray(), NO aquí. Llamar _setup_tray() en __init__
        # sin nunca invocar run()/run_detached() filtra un recurso: en
        # Win32, el constructor de pystray.Icon llama RegisterClassEx()
        # (clase de ventana con nombre "%s%dSystemTrayIcon" % (name, id(self)),
        # y ese _unregister_class() solo se ejecuta en el bloque finally de
        # _mainloop(), que nunca se llega a si run() no se llama. Si el icono
        # de init se GC'd y CPython reutiliza su id() para el icono creado en
        # el primer _minimize_to_tray() (y luego _setup_tray() del segundo
        # minimize reutiliza la misma id()), RegisterClassEx falla con
        # ERROR_CLASS_DUPLICATED, _setup_tray() atrapa la excepción y pone
        # self._tray = None → la ventana se oculta pero la bandeja no aparece
        # y el proceso se queda colgado (bug: "solo funciona una vez").
        self._load_session()   # restaurar lista de archivos de la sesión anterior
        _mark("_load_session()")
        # Sincronización de visionado programada -- a diferencia de
        # AutoWatcher (que solo arranca si se inicia minimizado o al
        # pulsar "Auto"), este hilo se arranca SIEMPRE: una hora
        # programada tiene que poder saltar sin importar cómo se abrió
        # la ventana esta vez. No hace nada si no hay programación
        # activada (comprueba config_data en caliente cada minuto, ver
        # _check_watch_sync_schedule).
        self._start_watch_sync_scheduler()
        _mark("_start_watch_sync_scheduler()")
        self._cleanup_stale_uploading_marks()   # ver docstring: limpia marcas "subiendo" de una sesión anterior cerrada a medias
        _mark("_cleanup_stale_uploading_marks()")
        # Antes, el indicador de espacio libre del toolbar solo se rellenaba
        # tras pulsar "Probar conexión" en Ajustes o al empezar una subida
        # -- así que en un arranque normal se veía vacío sin más. Se conecta
        # solo en segundo plano al arrancar (si hay servidor configurado)
        # para que ya esté relleno desde el primer momento. 3s (no 400ms):
        # con la app arrancando junto a Windows, un intento demasiado
        # pronto puede toparse con la red todavía sin terminar de
        # inicializarse -- visto de verdad: funcionaba al empezar una
        # subida más tarde (red ya lista) pero no en el primer intento.
        # Instrumentación temporal (ver _mark arriba): estas dos miden lo
        # que queda FUERA de __init__ -- el primer ciclo de mainloop() y
        # el primer pintado real de la ventana en pantalla. Todo lo de
        # arriba mide "cuánto tarda en construirse", esto mide "cuánto
        # tarda en verse de verdad" -- si hay un hueco grande entre el
        # total de __init__ y estas dos marcas, el tiempo se va DENTRO de
        # mainloop(), no en nada de lo ya medido.
        self.after(0, lambda: _log.info(
            "Arranque: primer ciclo de mainloop()               total %6.0f ms desde __init__",
            (_time.perf_counter() - _t0) * 1000))

        def _mark_first_map(event=None):
            self.unbind("<Map>", _map_bind_id[0])
            _log.info("Arranque: primera vez visible en pantalla (<Map>)   total %6.0f ms desde __init__",
                      (_time.perf_counter() - _t0) * 1000)
        _map_bind_id = [None]
        _map_bind_id[0] = self.bind("<Map>", _mark_first_map, add="+")

        self.after(3000, self._refresh_ftp_space_at_startup)
        self.after(3500, self._check_for_updates_at_startup)
        # Configuración compartida del servidor (TMDB/IA, plantillas,
        # categorías, servidores de medios, enlaces, cuota de reservas...)
        # -- ver core/server_config.py. Silencioso si no hay ruta
        # configurada o la descarga falla; los valores locales se quedan
        # como estaban.
        # Antes que las sincronizaciones de abajo: tras el cambio de nombre de
        # la aplicación, los datos que el grupo comparte están todavía con el
        # nombre anterior y hay que traerlos (una sola vez, ver el método).
        self.after(300, self._migrate_shared_data_folder)
        self.after(400, self._migrate_autostart_identity)
        self.after(2200, self._sync_server_config_from_ftp)
        # Episodios que faltan y Películas: la caché compartida se refresca
        # desde el FTP también al abrir la app (no solo al entrar en cada
        # pestaña) -- así un cliente que la tiene abierta en otra pestaña
        # se entera igualmente de los cambios que otro usuario hizo (p.ej.
        # un capítulo ya subido que ya no falta), sin tener que visitar la
        # pestaña a mano. El freno _*_SYNC_MIN_INTERVAL evita repetir la
        # consulta si el <FocusIn> de arranque ya la hizo.
        self.after(2300, self._sync_missing_episodes_from_ftp)
        self.after(2400, self._sync_missing_movies_from_ftp)
        # Detector de episodios que faltan: comprobación periódica en
        # segundo plano (silenciosa, sin diálogo) para que la caché esté ya
        # al día cuando el usuario abra el diálogo a mano -- ver
        # _maybe_background_missing_scan.
        self.after(60_000, self._maybe_background_missing_scan)
        # Reanudar el modo automático si estaba en marcha al cerrar la app
        # la última vez (ver _restore_auto_watcher_state) -- siempre, no
        # solo con --minimized: el botón "⚡ Auto" debe recordar su estado
        # tanto si la app se abre a mano como por el autoarranque.
        self.after(400, self._restore_auto_watcher_state)
        self.after(600, self._start_missing_ep_auto_worker)
        if "--minimized" in sys.argv:
            self.after(200, self._minimize_to_tray)

        # Los callbacks de Tk (binds, after...) que lancen una excepción se
        # pierden por stderr por defecto y no aparecen en app.log -- con lo
        # que un fallo de repintado (p.ej. un error al construir una fila de
        # "Episodios que faltan") dejaba medio-renderizada la tabla sin dejar
        # ningún rastro. Este hook vuelca la traza a _log para poder
        # diagnosticarlo.
        try:
            self.report_callback_exception = self._report_callback_exception
        except Exception:
            pass

    def _report_callback_exception(self, exc, val, tb):
        import traceback
        _log.error("Excepción en callback de Tk:\n%s",
                   "".join(traceback.format_exception(exc, val, tb)))

    def _apply_icon(self, window):
        """Aplica el icono de la app a *window* (ventana principal o cualquier
        popup/diálogo Toplevel) — iconbitmap(default=...) no se propaga de
        forma fiable a los Toplevel hijos, así que se aplica explícitamente.
        Windows usa el .ico vía iconbitmap(); macOS/Linux usan el PNG vía
        iconphoto(), que es lo que Tk soporta ahí."""
        try:
            if self._icon_path:
                window.iconbitmap(self._icon_path)
            elif self._icon_photo:
                window.iconphoto(True, self._icon_photo)
        except Exception:
            pass

    def _apply_window_state(self):
        """Restaura el tamaño/posición (y el estado maximizado, si aplica)
        de la ventana principal guardados al cerrar la última vez (ver
        _save_window_state). La geometría se aplica antes de entrar en
        mainloop; el maximizado se agenda con after porque Tk necesita que
        la ventana esté ya creada/visible para cambiar de estado."""
        geom = self.config_data.get("window_geometry") or ""
        if geom:
            try:
                self.geometry(geom)
            except Exception:
                pass
        if self.config_data.get("window_maximized"):
            self.after(100, lambda: self._restore_maximized())

    def _restore_maximized(self):
        try:
            self.state("zoomed")
        except Exception:
            pass

    def _save_window_state(self):
        """Guarda el estado actual de la ventana principal (geometría +
        maximizada/no) en la config, para restaurarlo en el próximo
        arranque. Se llama al cerrar (ver _force_quit). Si la ventana está
        maximizada, se guarda su geometría enmarcada y la marca de
        maximizada; si no, solo la geometría."""
        try:
            maximized = self.state() == "zoomed"
            if maximized:
                # En maximizado, geometry() devuelve la geometría de
                # pantalla completa del escritorio -- guardar esa no tiene
                # sentido para restaurar el tamaño normal; mejor conservar
                # la que tenía antes de maximizar si se conoce.
                geom = self.config_data.get("window_geometry") or self.geometry()
            else:
                geom = self.geometry()
            self.config_data.set("window_geometry", geom)
            self.config_data.set("window_maximized", maximized)
        except Exception:
            pass

    # ------------------------------------------------------------------ UI --

    def _build_ui(self):
        self.grid_columnconfigure(0, weight=1)
        self.grid_rowconfigure(1, weight=1)
        self.grid_rowconfigure(2, weight=0)

        # Cabecera responsiva -- ver _update_header_responsive_layout. El
        # ancho natural de la cabecera (con las 8 pestañas de navegación)
        # supera el ancho mínimo configurado de la ventana (self.minsize)
        # -- por debajo de ese umbral, la navegación se colapsa en un
        # único botón "☰" (ver _header_needed_width, recalculado en cada
        # redimensionado, no cacheado de una sola medición al arrancar).
        self._header_compact_mode = None
        self._root_resize_after_id = None
        self._nav_overflow_popup = None   # ver _show_nav_overflow_menu
        self._build_header()
        self._startup_mark("  _build_header()")
        # Primer chequeo tras construir la cabecera -- después de esto,
        # cada <Configure> de la ventana (_on_root_resize) ya lo mantiene
        # al día solo. after(0, ...): winfo_reqwidth() necesita que Tk
        # haya calculado el layout al menos un ciclo antes de poder leerlo
        # (ver _header_needed_width, que además ya fuerza su propio
        # update_idletasks() por si acaso).
        self.after(0, self._update_header_responsive_layout)

        self._main_frame = ctk.CTkFrame(self, fg_color="transparent")
        self._main_frame.grid(row=1, column=0, sticky="nsew", padx=10, pady=(CONTAINER_GAP, CONTAINER_GAP))
        self._main_frame.grid_columnconfigure(0, weight=1)
        self._main_frame.grid_rowconfigure(0, weight=1)

        # Vista de archivos (siempre presente, se oculta al abrir las otras)
        self._files_frame = ctk.CTkFrame(self._main_frame, fg_color="transparent")
        self._files_frame.grid(row=0, column=0, sticky="nsew")
        self._files_frame.grid_columnconfigure(0, weight=1)
        self._build_files_tab(self._files_frame)
        self._startup_mark("  _build_files_tab()")

        # Vista de episodios que faltan (oculta por defecto) -- pantalla
        # completa igual que Archivos, no un diálogo aparte: es una sección
        # tan importante como la principal.
        self._missing_ep_frame = ctk.CTkFrame(self._main_frame, fg_color="transparent")
        self._missing_ep_frame.grid_columnconfigure(0, weight=1)
        # El peso de fila lo pone _build_missing_episodes_tab sobre su
