    def _attach_pagination_tooltips(self):
        """Tooltip a los "< Anterior"/"Siguiente >" de todas las tablas de una
        pasada.

        Son nueve pares idénticos repartidos por seis pestañas; ponerlos a mano
        uno a uno era garantizar que al añadir la décima tabla se olvidara. Se
        recorren por convención de nombre (_*_prev_btn / _*_next_btn), así que
        una tabla nueva lo hereda sin tocar nada aquí."""
        for nombre in dir(self):
            if not (nombre.endswith("_prev_btn") or nombre.endswith("_next_btn")):
                continue
            widget = getattr(self, nombre, None)
            if not isinstance(widget, ctk.CTkButton):
                continue
            anterior = nombre.endswith("_prev_btn")
            attach_tooltip(widget, lambda ant=anterior: (
                "Página anterior de la lista." if ant else "Página siguiente de la lista.") +
                " La selección NO se pierde al cambiar de página: sigue afectando a todas.")

    def _build_header(self):
        header = ctk.CTkFrame(self, height=56, corner_radius=0)
        header.grid(row=0, column=0, sticky="ew")
        header.grid_columnconfigure(2, weight=1)
        self._header = header

        # Sin etiqueta "aIBechos" aquí -- el título ya se ve en la barra
        # de la ventana (self.title(), ver __init__) y duplicarlo en la
        # cabecera solo quitaba espacio a la navegación sin aportar nada.
        # Navegación: las 4 vistas como pestañas conectadas (una activa a
        # la vez), en vez de botones de alternancia sueltos -- Archivos
        # tiene su propia pestaña ahora, igual que las demás.
        self._nav_segmented = ctk.CTkSegmentedButton(
            header, values=list(self._NAV_LABELS.values()), height=30, border_width=1,
            command=self._on_nav_segment_changed)
        self._nav_segmented.set(self._NAV_LABELS["files"])
        self._nav_segmented.grid(row=0, column=1, padx=(20, 16))

        # Botón "☰" -- colapsa la navegación (Archivos/Episodios/Liberar
        # espacio/.../Configuración -- 8 pestañas) en un único menú cuando
        # la ventana no tiene ancho de sobra (ver
        # _update_header_responsive_layout/_show_nav_overflow_menu). Mismo
        # hueco (columna 1) que ocupa _nav_segmented -- nunca conviven
        # visibles a la vez.
        self._nav_menu_btn = ctk.CTkButton(
            header, text="☰", height=30, width=40, font=ctk.CTkFont(size=15),
            fg_color="transparent", border_width=1,
            command=self._show_nav_overflow_menu)
        attach_tooltip(self._nav_menu_btn, lambda: "Menú de navegación: las mismas pestañas de "
                       "siempre, agrupadas aquí porque la ventana no da de ancho. Ensánchala y "
                       "vuelven a salir arriba.")
        self._nav_menu_btn.grid(row=0, column=1, padx=(20, 16))
        self._nav_menu_btn.grid_remove()   # oculto salvo en modo compacto

        self._ftp_space_lbl = ctk.CTkLabel(
            header, text="", font=ctk.CTkFont(size=12),
            text_color=PENDING_COLOR)
        self._ftp_space_lbl.grid(row=0, column=3, padx=10)

        # Separador visual: a partir de aquí son ACCIONES (guardar,
        # automático, minimizar), no vistas a las que navegar.
        ctk.CTkFrame(header, width=1, height=30, fg_color=("gray70", "gray35")).grid(
            row=0, column=4, sticky="ns", padx=(4, 12))

        self._save_settings_btn = ctk.CTkButton(
            header, text="💾 Guardar configuración", width=170, height=30,
            fg_color=ACCENT, hover_color=ACCENT_HOVER,
            command=self._save_all_settings)
        attach_tooltip(self._save_settings_btn, lambda: "Guardar los cambios de Ajustes. Hasta "
                       "que pulses aquí no se aplica nada de lo que hayas tocado.")
        self._save_settings_btn.grid(row=0, column=5, padx=(0, 8))
        self._save_settings_btn.grid_remove()   # solo visible dentro de Ajustes
        self._auto_btn = ctk.CTkButton(
            header, text="⚡ Auto", width=90, height=30,
            fg_color="transparent", border_width=1,
            command=self._toggle_auto)
        attach_tooltip(self._auto_btn, lambda: (
            "Modo automático ACTIVO: vigila la carpeta configurada y, según los Ajustes, "
            "identifica, renombra y sube lo que aparezca sin que tengas que hacer nada. "
            "Pulsa para pararlo." if (self._watcher and self._watcher.running) else
            "Modo automático parado. Al activarlo vigila la carpeta configurada en Ajustes e "
            "identifica, renombra y sube solo lo que vaya apareciendo."))
        self._auto_btn.grid(row=0, column=6, padx=(0, 8))
        self._tray_btn = ctk.CTkButton(
            header, text="⊟", width=36, height=30,
            fg_color="transparent", border_width=1,
            command=self._minimize_to_tray)
        attach_tooltip(self._tray_btn, lambda: "Minimizar al área de notificación. La app sigue "
                       "funcionando (el modo automático incluido); se recupera con doble clic "
                       "en su icono.")
        self._tray_btn.grid(row=0, column=7, padx=(0, 16))

        self.bind("<Configure>", self._on_root_resize, add="+")
        # Volver a la app (p.ej. tras minimizar a bandeja o trabajar en otra
        # ventana): refrescar las cachés compartidas de "Episodios que
        # faltan" y "Películas" desde el FTP, igual que al arrancar -- así
        # el usuario ve los cambios que otro cliente hizo mientras tanto,
        # sin tener que salir y volver a entrar en cada pestaña. El freno
        # _*_SYNC_MIN_INTERVAL amortigua los <FocusIn> que Tk dispara con
        # frecuencia (cada vez que cambia el foco entre widgets hijos).
        self.bind("<FocusIn>", self._on_root_focus_in, add="+")

    def _on_root_focus_in(self, event=None):
        if event is not None and event.widget is not self:
            return
        self._sync_missing_episodes_from_ftp()
        self._sync_missing_movies_from_ftp()

    def _header_needed_width(self) -> int:
        """Ancho necesario AHORA MISMO para mostrar toda la cabecera con
        _nav_segmented visible (en vez de su versión colapsada "☰") --
        recalculado en directo en cada redimensionado, NO cacheado de una
        sola medición al arrancar.

        Bug real de la primera versión de esto: se medía self._header.
        winfo_reqwidth() una sola vez al arrancar y se guardaba como
        umbral fijo para toda la sesión -- pero en ese momento
        _ftp_space_lbl todavía estaba vacía ("" -- el espacio libre del
        FTP tarda un poco en llegar tras abrir la app), así que el umbral
        medido salía DE MENOS de lo que la cabecera necesita de verdad en
        cuanto esa etiqueta tiene texto real. Resultado: con la ventana en
        un ancho intermedio, el umbral (de menos) decía "todavía cabe
        todo" y no colapsaba la navegación, pero "Auto"/"⊟" sí quedaban
        recortados por el borde de la ventana, que es justo lo que se
        veía. Sumar cada ancho por separado y leerlos en el momento evita
        depender de una foto fija tomada demasiado pronto.

        _nav_segmented.winfo_reqwidth() se lee siempre (esté colapsado o
        no ahora mismo) -- un widget oculto con grid_remove() sigue
        reportando su tamaño natural, no hace falta mostrarlo para medirlo.

        "Guardar configuración" SÍ se cuenta solo si está visible ahora
        mismo (winfo_ismapped(), fuera de Ajustes no ocupa sitio de verdad)
        -- reservar sus ~178px SIEMPRE (estuviera o no visible) fue
        demasiado conservador y colapsaba la navegación antes de que
        hiciera falta de verdad la inmensa mayoría del tiempo (fuera de
        Ajustes)."""
        self._header.update_idletasks()
        save_w = self._save_settings_btn.winfo_reqwidth() + 8 if self._save_settings_btn.winfo_ismapped() else 0
        return (
            20 + self._nav_segmented.winfo_reqwidth() + 16       # padx del nav
            + 10 + self._ftp_space_lbl.winfo_reqwidth()           # padx del espacio FTP
            + 4 + 12                                              # separador
            + save_w                                              # Guardar (solo si está visible ahora)
            + self._auto_btn.winfo_reqwidth() + 8                 # Auto
            + self._tray_btn.winfo_reqwidth() + 16                # bandeja
        )

    def _on_root_resize(self, event):
        if event.widget is not self:
            return   # <Configure> también burbujea desde widgets hijos -- solo interesa el de la ventana
        self._schedule_header_layout_check()

    def _schedule_header_layout_check(self):
        """Debounce compartido para _update_header_responsive_layout --
        además de en cada redimensionado de la ventana (_on_root_resize),
        hace falta llamarlo también cuando cambia el TEXTO de
        _ftp_space_lbl (_refresh_ftp_space, cada 5 min): cambiar el texto
        de una etiqueta NO redimensiona la ventana en sí (solo su
        contenido interno), así que ningún <Configure> del root se
        dispara solo por eso -- bug real: el umbral se recalcula bien
        (ver _header_needed_width), pero si nada llama a este método, ese
        recálculo nunca llega a ejecutarse, y la navegación se queda sin
        colapsar aunque el texto real de esa etiqueta ya no quepa."""
        if self._root_resize_after_id is not None:
            self.after_cancel(self._root_resize_after_id)
        self._root_resize_after_id = self.after(150, self._update_header_responsive_layout)

    def _update_header_responsive_layout(self):
        """Colapsa la navegación (Archivos/Episodios/.../Configuración --
        8 pestañas, con diferencia lo más ancho de la cabecera, ~806px) en
        el botón "☰" cuando la ventana no tiene ancho de sobra. Los
        botones de acción (Guardar/Auto/Minimizar) NO se tocan -- siguen
        visibles siempre, tal cual estaban antes de este cambio; colapsar
        solo la navegación ya libera de sobra el espacio que necesitan."""
        self._root_resize_after_id = None
        compact = self.winfo_width() < self._header_needed_width()
        if compact == self._header_compact_mode:
            return
        self._header_compact_mode = compact
        self._close_nav_overflow_menu()   # el botón que lo abrió puede estar a punto de ocultarse
        if compact:
            self._nav_segmented.grid_remove()
            self._nav_menu_btn.grid()
        else:
            self._nav_menu_btn.grid_remove()
            self._nav_segmented.grid()

    def _show_nav_overflow_menu(self):
        """Menú del botón "☰" -- las mismas 8 vistas que _nav_segmented,
        reconstruido cada vez que se abre. Panel propio (CTkToplevel sin
        decoración + CTkButtons) en vez de un tk.Menu nativo del SO -- el
        menú nativo se veía siempre con los colores por defecto del
        sistema (gris claro fijo), desentonando por completo con el tema
        oscuro de la app; este respeta el tema actual y resalta la vista
        activa, igual que ya hace _nav_segmented."""
        if self._nav_overflow_popup is not None:
            self._close_nav_overflow_menu()
            return

        popup = ctk.CTkToplevel(self)
        popup.overrideredirect(True)
        try:
            popup.attributes("-topmost", True)
        except Exception:
            pass
        x = self._nav_menu_btn.winfo_rootx()
        y = self._nav_menu_btn.winfo_rooty() + self._nav_menu_btn.winfo_height() + 4
        popup.geometry(f"+{x}+{y}")

        frame = ctk.CTkFrame(popup, corner_radius=8, border_width=1,
                              border_color=("gray70", "gray30"))
        frame.pack(fill="both", expand=True, padx=1, pady=1)

        current_key = self._current_view_key()
        for key, label in self._NAV_LABELS.items():
            is_active = key == current_key
            btn = ctk.CTkButton(
                frame, text=label, anchor="w", corner_radius=6, height=34,
                fg_color=ACCENT if is_active else "transparent",
                hover_color=ACCENT_HOVER if is_active else ("gray85", "gray25"),
                text_color="white" if is_active else None,
                command=lambda k=key: self._on_nav_overflow_select(k))
            btn.pack(fill="x", padx=6, pady=3)

        # Cerrar al perder el foco (clic fuera) o con Escape -- un menú
        # nativo (tk.Menu) se cierra solo en ambos casos; un CTkToplevel
        # normal no, hay que hacerlo a mano.
        popup.bind("<FocusOut>", lambda e: self._close_nav_overflow_menu())
        popup.bind("<Escape>", lambda e: self._close_nav_overflow_menu())
        popup.focus_force()
        self._nav_overflow_popup = popup

    def _on_nav_overflow_select(self, key: str):
        """Bug real: a veces el panel se quedaba visible en pantalla tras
        elegir una opción -- este callback corre DESDE DENTRO del propio
        procesamiento de clic del CTkButton, así que destruir el
        CTkToplevel que lo contiene en ese mismo instante (antes de que Tk
        termine de procesar ese clic) podía dejar el repintado a medias en
        algunos casos (más aún tratándose de un overrideredirect(True),
        que no tiene ayuda del gestor de ventanas para repintar). Cambiar
        de vista (_show_view) también puede tardar un momento (sincroniza
        con el FTP, reconstruye paneles...) -- si ese trabajo arranca
        ANTES de que el cierre del panel se refleje en pantalla, el hueco
        del panel podía quedarse "congelado" hasta el siguiente repintado
        de cualquier otra cosa. _close_nav_overflow_menu() ya oculta el
        panel al instante (withdraw()) antes de destruirlo -- separar
        _show_view en un after(0, ...) aparte le da a Tk un ciclo de
        inactividad de por medio para completar ese repintado antes de
        ponerse con el trabajo más pesado del cambio de vista."""
        self._close_nav_overflow_menu()
        self.after(0, lambda: self._show_view(key))

    def _close_nav_overflow_menu(self):
        popup = self._nav_overflow_popup
        if popup is None:
            return
        self._nav_overflow_popup = None
        try:
            # Desligar los binds ANTES de nada -- si no, un <FocusOut>
            # pendiente (p.ej. el que dispara este mismo cierre) podía
            # llegar a intentar procesarse sobre un widget ya destruido a
            # medias en la siguiente vuelta del bucle de eventos.
            popup.unbind("<FocusOut>")
            popup.unbind("<Escape>")
        except Exception:
            pass
        try:
            # withdraw() antes de destroy(): oculta la ventana del SO al
            # instante, sin esperar a que Tk termine de liberar el widget
            # -- un CTkToplevel con overrideredirect(True) no tiene ayuda
            # del gestor de ventanas para repintar solo, así que destroy()
            # por sí solo podía dejarlo visualmente "pegado" en pantalla
            # unos instantes (visto de verdad, sobre todo si justo después
            # arrancaba trabajo más pesado -- ver _on_nav_overflow_select).
            popup.withdraw()
        except Exception:
            pass
        try:
            popup.destroy()
        except Exception:
            pass

    def _build_status_bar(self):
        bar = ctk.CTkFrame(self, height=28, corner_radius=0)
        bar.grid(row=2, column=0, sticky="ew")
        bar.grid_columnconfigure(1, weight=1)
        self._status_bar_left = ctk.CTkLabel(
            bar, text="", font=ctk.CTkFont(size=11), text_color=PENDING_COLOR, anchor="w")
        self._status_bar_left.grid(row=0, column=0, sticky="w", padx=12, pady=4)
        # Mensajes de estado/error de _set_status (antes en la cabecera,
        # ver _status_lbl) -- columna central, la única con weight=1 (el
        # hueco que antes quedaba vacío entre el recuento de archivos y la
        # selección actual), para que todo mensaje de la app salga por la
        # barra de estado inferior en vez de arriba.
        self._status_bar_center = ctk.CTkLabel(
            bar, text="", font=ctk.CTkFont(size=11), text_color=ACCENT, anchor="center")
        self._status_bar_center.grid(row=0, column=1, sticky="ew", padx=12, pady=4)
        self._status_bar_right = ctk.CTkLabel(
            bar, text="", font=ctk.CTkFont(size=11), text_color=PENDING_COLOR, anchor="e")
        self._status_bar_right.grid(row=0, column=2, sticky="e", padx=12, pady=4)
        self._update_status_bar()

    def _update_status_bar(self):
        n = len(self.files)
        if n == 0:
            self._status_bar_left.configure(text="Sin archivos en la lista")
        else:
            total_size = 0
            counts = {}
            for e in self.files:
                counts[e.status] = counts.get(e.status, 0) + 1
                # Cacheado tras el primer stat() con éxito (ver
                # FileEntry._last_known_size_bytes) -- esta función se llama
                # tras CADA actualización de fila (subida, renombrado,
                # AutoWatcher...), y antes volvía a leer el tamaño en disco
                # de TODOS los archivos de la lista en cada llamada: con una
                # cola de cientos de archivos, cada actualización de fila
                # disparaba un barrido O(n) completo -- O(n²) stat() en
                # total para un lote grande. El tamaño de un vídeo ya en
                # disco no cambia bajo esta app (AutoWatcher espera a que se
                # estabilice antes de procesarlo), así que reutilizarlo es
                # seguro; mismo criterio ya aceptado para
                # _last_known_size_text.
                if e._last_known_size_bytes is None:
                    try:
                        e._last_known_size_bytes = Path(e.path).stat().st_size
                    except OSError:
                        pass
                if e._last_known_size_bytes is not None:
                    total_size += e._last_known_size_bytes
            labels = {
                "pendiente": "pendientes", "buscando": "buscando", "listo": "listos",
                "renombrado": "renombrados", "en_cola": "en cola para subir",
                "subiendo": "subiendo", "subido": "subidos",
                "error": "con error", "auto": "en automático", "omitido": "omitidos",
            }
            breakdown = " · ".join(f"{cnt} {labels.get(st, st)}" for st, cnt in counts.items() if cnt)
            parts = [f"{n} archivo{'s' if n != 1 else ''}", _fmt_size(total_size)]
            if breakdown:
                parts.append(breakdown)
            # Suma de la velocidad de TODAS las subidas en curso ahora mismo
            # (entry.ftp_speed, ya lo mantiene vivo el propio callback de
            # progreso de cada subida, ver _upload_one::progress) -- con
            # "Subidas simultáneas" > 1 esto es justo lo que no se ve fila a
            # fila, cuánto se está aprovechando de verdad el ancho de banda
            # disponible en conjunto.
            total_speed = sum(e.ftp_speed for e in self.files if e.status == "subiendo")
            # Cada sumando ya viene suavizado, pero sus lecturas no van
            # acompasadas entre sí y el total todavía da escalones al sumarlas.
            # Una segunda pasada corta lo deja quieto.
            if total_speed > 0:
                total_speed = self._total_speed_media.update(
                    total_speed, _time.monotonic())
                parts.append(f"Subiendo: {_fmt_speed(total_speed)}")
            else:
                self._total_speed_media.reset()   # que la próxima no arrastre
            self._status_bar_left.configure(text="   ·   ".join(parts))

        # El texto de la derecha refleja la selección de la vista ACTIVA
        # ahora mismo, no siempre self._selected_entry (que es solo de
        # Archivos) -- antes, estando en Episodios o Liberar espacio con
        # algo pulsado, aquí seguía poniendo "Ningún archivo seleccionado"
        # sin más, aunque sí hubiera algo seleccionado en esa vista.
        view = self._current_view_key()
        if view == "cleanup":
            item = self._cleanup_selected_item
            if item is not None:
                self._status_bar_right.configure(
                    text=f"Seleccionado: {item.name}  ({_fmt_size(item.size_bytes)})")
            else:
                self._status_bar_right.configure(text="Ninguna candidata seleccionada")
        elif view == "missing_ep":
            row = self._missing_ep_current_row
            if row is not None:
                # No hay tamaño que mostrar de verdad -- son episodios que
                # faltan, ni siquiera se han descargado -- pero se deja el
                # mismo formato "Nombre (dato)" que Liberar espacio en vez
                # de omitirlo sin más, para no parecer que falta algo.
                self._status_bar_right.configure(text=f"Seleccionado: {row['name']}  (tamaño desconocido)")
            else:
                self._status_bar_right.configure(text="Ninguna serie seleccionada")
        elif view == "files":
            if self._selected_entry is not None:
                e = self._selected_entry
                try:
                    size_str = _fmt_size(Path(e.path).stat().st_size)
                except OSError:
                    size_str = "?"
                text = f"Seleccionado: {e.name}  ({size_str})"
                remote = self._preview_remote_path(e)
                if remote:
                    text += f"   →   {remote}"
                self._status_bar_right.configure(text=text)
            else:
                self._status_bar_right.configure(text="Ningún archivo seleccionado")
        else:
            self._status_bar_right.configure(text="")

    def _preview_remote_path(self, entry) -> str:
        """Ruta FTP de destino para *entry* -- si el usuario la ha fijado a
        mano (columna "Destino" de la tabla), esa gana; si no, se prueba
        primero si ya hay carpeta en OTRA categoría (usando solo lo que ya
        esté en caché -- ver _find_category_with_existing_folder, y
        _prefetch_ftp_category_dirs para cuándo se rellena esa caché) y,
        si no, la que le correspondería por categoría/género. No se
        conecta al servidor por su cuenta ni bloquea la interfaz -- si
        hace falta listar una carpeta que no está ya en caché, eso solo
        pasa de verdad al subir (ver _upload_entry_with)."""
        filename = entry.new_name or Path(entry.path).name
        if entry.remote_dir_override:
            return f"{entry.remote_dir_override.rstrip('/')}/{filename}"
        info = entry.media_info
        if not info:
            return ""
        category = self._category_for(info)
        serie_name = info.title
        if info.media_type == "tv":
            existing_category, existing_name = self._find_category_with_existing_folder(
                self.ftp, info, use_cache_only=True)
            if existing_category:
                category = existing_category
                serie_name = existing_name   # reutilizar el nombre EXACTO ya existente, no el título tal cual de TMDB
        if not category:
            return ""
        root = category.get("root", "")
        if not root:
            return ""
        full_tpl = root.rstrip("/") + "/" + category.get("template", "{serie}/")
        remote_dir = self.ftp.build_remote_path(
            full_tpl, serie_name, info.season, info.year, info.media_type)
        return f"{remote_dir.rstrip('/')}/{filename}"

    # ---------------------------------------------------------------- Files tab

    def _restore_auto_watcher_state(self):
        """Reanuda el modo automático al arrancar SI ya estaba en marcha la
        última vez que se cerró la app (ver "auto_watcher_running" en
        DEFAULTS, config.py) -- sustituye a la lógica anterior, que
        arrancaba siempre que hubiera una carpeta configurada (con
        --minimized, para el autoarranque con Windows/macOS): eso podía
        volver a encender el modo automático solo porque alguna vez se
        configuró una carpeta, aunque el usuario lo hubiera parado a mano
        antes de cerrar. Ahora se llama SIEMPRE al arrancar (no solo con
        --minimized), para que el botón "⚡ Auto" recuerde su estado entre
        reinicios igual que cualquier otro ajuste persistente."""
        was_running = self.config_data.get("auto_watcher_running", False)
        folder = self.config_data.get("watch_folder", "").strip()
        if was_running and folder and not (self._watcher and self._watcher.running):
            self._toggle_auto()

    def _toggle_auto(self):
        if self._watcher and self._watcher.running:
            self._watcher.stop()
            self._watcher = None
            self._auto_btn.configure(
                text="⚡ Auto", width=90, fg_color="transparent", border_width=1)
            self._set_status("Modo automático detenido", PENDING_COLOR)
            self.config_data.set("auto_watcher_running", False)
            self.config_data.save()
        else:
            folder = self.config_data.get("watch_folder", "").strip()
            if not folder:
                self._set_status(
                    "Configura la carpeta vigilada en ⚙ Configuración", WARNING_COLOR)
                return
            self._watcher = AutoWatcher(
                folder, self.config_data, self.tmdb, self.ftp,
                self._on_auto_event, self._on_auto_file_event,
                upload_slots=self._upload_slots, ftp_lock=self._ftp_cmd_lock,
                ftp_factory=self._new_ftp_client,   # que suba por el protocolo configurado
                comicvine_client=self.comicvine, book_client=self.book_client,
                openlibrary_client=self.openlibrary_client)
            self._watcher.start()
            self._auto_btn.configure(
                text="⏹ Detener", width=90, fg_color="#c0392b", hover_color="#96281b",
                border_width=0)
            self._set_status(f"Vigilando: {folder}", SUCCESS_COLOR)
            self.config_data.set("auto_watcher_running", True)
            self.config_data.save()

    def _on_auto_event(self, tipo, msg):
        colors = {"info": ACCENT, "ok": SUCCESS_COLOR,
                  "skip": WARNING_COLOR, "error": ERROR_COLOR}
        self.after(0, lambda: self._set_status(msg, colors.get(tipo, ACCENT)))

    def _on_auto_file_event(self, path, tipo, new_name=None, progress=None, speed=None,
                             media_info=None, confidence=None, reason=None, renamed_on_disk=True,
                             size=None, remote_full=None):
        """Recibe eventos de archivo del AutoWatcher y actualiza la tabla."""
        path = str(Path(path))   # normalizar separadores antes de comparar/asignar
        def _update():
            # Buscar entrada existente por path
            entry = next((e for e in self.files if e.path == path), None)
            if entry is None:
                # El archivo ya fue renombrado en un ciclo anterior (p.ej. la
                # subida FTP falló y AutoWatcher lo reprocesa): el path en disco
                # cambió pero sigue siendo el mismo archivo — buscarlo por el
                # nombre con el que quedó tras el renombrado para no duplicar la fila.
                fname = Path(path).name
                entry = next((e for e in self.files
                              if e.new_name == fname and e.status != "subido"), None)
                if entry is not None:
                    entry.path = path

            if tipo == "start":
                if entry is None:
                    entry = FileEntry(path)
                    entry.status = "auto"
                    self.files.append(entry)
                    self._refresh_table()
                else:
                    entry.status    = "auto"
                    entry.error_msg = ""   # nuevo intento -- descartar el motivo anterior
                    self._update_row(entry)
                return

            if entry is None:
                return  # archivo no en lista, ignorar

            if tipo == "renamed":
                entry.new_name = new_name or ""
                entry.status   = "renombrado"
                if media_info is not None:
                    entry.media_info = media_info
                if confidence is not None:
                    entry.confidence = confidence
                # El renombrado es en la misma carpeta: el archivo real ahora
                # vive en <misma carpeta>/<new_name>, no en la ruta original
                # con la que se detectó. Sin esto, cualquier acción manual
                # posterior sobre esta entrada (subir, ver detalles) usaba una
                # ruta que ya no existe en disco ("Archivo no encontrado").
                # Si "Renombrar en origen" está desactivado, el archivo real
                # NO se tocó — entry.path debe seguir apuntando al original.
                if new_name and renamed_on_disk:
                    entry.path = str(Path(path).parent / new_name)
                self._update_row(entry)
                if self._selected_entry is entry:
                    self._update_detail(entry)

            elif tipo == "queued":
                # Ya se resolvió categoría/duplicado/espacio, pero todavía
                # no hay turno de "Subidas simultáneas" -- si varios
                # archivos se detectaron a la vez, todos pasan por aquí casi
                # al mismo tiempo, y solo uno de ellos conseguirá turno real
                # (ver "uploading" más abajo, que si eso sí pisa este
                # estado en cuanto empieza a transferir de verdad).
                entry.status       = "en_cola"
                entry.new_name     = new_name or entry.new_name
                self._update_row(entry)

            elif tipo == "uploading":
                entry.status       = "subiendo"
                entry.ftp_progress = progress or 0.0
                entry.ftp_speed    = speed or 0.0
                entry.new_name     = new_name or entry.new_name
                self._update_row(entry)
                self._ftp_row_live(entry, entry.ftp_progress, entry.ftp_speed)

            elif tipo == "uploaded":
                entry.status       = "subido"
                entry.ftp_progress = 1.0
                entry.ftp_speed    = 0.0
                entry.new_name     = new_name or entry.new_name
                self._update_row(entry)
                self._ftp_row_live(entry, 1.0, 0.0)
                # Notificación de escritorio -- agrupada, ver
                # _queue_upload_notification (no una por archivo).
                fname = entry.new_name or entry.name
                self._queue_upload_notification(fname)
                # Guardar en historial (modo automático) -- size viene del
                # propio AutoWatcher (ya lo calculó antes de subir, ver
                # core/auto_watcher.py), NO recalculado aquí: en este punto
                # el archivo pudo moverse/borrarse ya (mover a "procesados"
                # o eliminar tras subir), así que Path(path).stat() podría
                # fallar o dar un tamaño distinto al que de verdad se subió.
                # remote_full lo manda AutoWatcher; antes se guardaba aquí
                # la ruta LOCAL en el campo "remote", con lo que el historial
                # no sabía dónde había quedado el archivo en el servidor.
                # El "or path" solo cubre a un AutoWatcher que no lo envíe.
                # filename = entry.name (el ORIGINAL, nunca se sobreescribe
                # al renombrar -- ver FileEntry) para que el historial
                # muestre el nombre con el que llegó el archivo, no el que
                # se le puso al renombrar; el nombre final sigue visible en
                # la columna "destino" (remote incluye el nombre remoto).
                self._save_history_entry(entry.name, remote_full or path, "ok", size or 0,
                                          local_path=path)
                self._remove_uploaded_episode_from_missing_list(entry.media_info)
                self._remove_uploaded_movie_from_movies_list(entry.media_info)
                self._refresh_ftp_space()

            elif tipo == "skip":
                entry.status    = "omitido"
                entry.new_name  = new_name or entry.new_name
                entry.error_msg = reason or ""
                self._update_row(entry)
                if self._selected_entry is entry:
                    self._update_detail(entry)

            elif tipo == "error":
                entry.status    = "error"
                entry.error_msg = reason or ""
                entry.new_name  = new_name or entry.new_name
                if media_info is not None:
                    entry.media_info = media_info
                if confidence is not None:
                    entry.confidence = confidence
                self._update_row(entry)
                if self._selected_entry is entry:
                    self._update_detail(entry)

        self.after(0, _update)

    # Navegación unificada (barra de pestañas segmentada en el header,
    # ver _build_header) -- las 4 vistas (Archivos/Episodios/Historial/
    # Configuración) se tratan igual, una activa a la vez, en vez de
    # botones de alternancia independientes cada uno con su propia lógica.
    _NAV_LABELS = {
        "files": "📁 Archivos",
        "movies": "🎬 Recomendado",
        "missing_ep": "🔍 Episodios",
        "downloads": "📥 Descargar",
        "cleanup": "🗑 Liberar espacio",
        "protected": "🔒 Protegidos",
        "history": "📋 Historial",
        "watch_sync": "🔄 Sincronizar visionado",
        "stats": "📊 Estadísticas",
        "config": "⚙ Configuración",
    }

    def _current_view_key(self) -> str:
        if self._config_visible:
            return "config"
        if self._missing_ep_visible:
            return "missing_ep"
        if self._movies_visible:
            return "movies"
        if self._downloads_visible:
            return "downloads"
        if self._history_visible:
            return "history"
        if self._cleanup_visible:
            return "cleanup"
        if self._protected_visible:
            return "protected"
        if self._watch_sync_top_visible:
            return "watch_sync"
        if self._stats_visible:
            return "stats"
        return "files"

    def _on_nav_segment_changed(self, value):
        key = next((k for k, v in self._NAV_LABELS.items() if v == value), "files")
        self._show_view(key)

    def _show_view(self, view_key: str):
        """Cambia a la vista *view_key* -- envoltorio fino sobre
        _show_view_impl solo para medir cuánto tarda un cambio de pantalla
        de verdad (ver app.log, mismo hábito que el "Arranque: ..." de
        __init__) sin tener que instrumentar cada return anticipado de
        _show_view_impl por separado."""
        if view_key == self._current_view_key():
            return
        _t0 = _time.perf_counter()
        try:
            self._show_view_impl(view_key)
        finally:
            _log.info("Vista: _show_view('%s') %6.0f ms", view_key, (_time.perf_counter() - _t0) * 1000)

    def _show_view_impl(self, view_key: str):
        """Cambia a la vista *view_key* ("files"/"missing_ep"/"history"/
        "config"), ocultando la que estuviera activa. Si se sale de
        Ajustes con cambios sin guardar y el usuario cancela, la pestaña
        segmentada vuelve a marcar Configuración en vez de quedarse en el
        valor a medio pulsar."""
        if self._config_visible:
            try:
                dirty = self._settings_dirty()
            except Exception:
                # Si no se puede comprobar con seguridad, asumir que SÍ hay
                # cambios sin guardar -- lo contrario (asumir que no los
                # hay) se probó y arriesga perder cambios de verdad en
                # silencio, que es mucho peor que preguntar de más. Se
                # registra para poder diagnosticar la causa real si vuelve
                # a pasar, en vez de seguir adivinando.
                _log.warning("_settings_dirty() falló al comprobar cambios sin guardar, "
                             "se asume que sí los hay", exc_info=True)
                dirty = True
            if dirty:
                try:
                    dlg_result = _UnsavedSettingsDialog(self).result
                except Exception:
                    # Si el propio diálogo falla al construirse, quedarse en
                    # Configuración (no perder cambios) en vez de salir sin
                    # preguntar -- el usuario sigue pudiendo guardar a mano
                    # con el botón "Guardar configuración", que sigue visible.
                    _log.warning("_UnsavedSettingsDialog falló al construirse, "
                                 "se mantiene la vista en Configuración", exc_info=True)
                    self._nav_segmented.set(self._NAV_LABELS["config"])
                    return
                if dlg_result == "save":
                    self._save_all_settings()
                elif dlg_result != "discard":
                    self._nav_segmented.set(self._NAV_LABELS["config"])
                    return
            self._config_panel_frame.grid_remove()
            self._config_visible = False
            self._save_settings_btn.grid_remove()
            self._schedule_header_layout_check()
        elif self._missing_ep_visible:
            self._missing_ep_frame.grid_remove()
            self._missing_ep_visible = False
        elif self._movies_visible:
            self._movies_frame.grid_remove()
            self._movies_visible = False
        elif self._history_visible:
            self._history_frame.grid_remove()
            self._history_visible = False
        elif self._cleanup_visible:
            self._cleanup_frame.grid_remove()
            self._cleanup_visible = False
        elif self._protected_visible:
            self._protected_frame.grid_remove()
            self._protected_visible = False
        elif self._watch_sync_top_visible:
            self._watch_sync_top_frame.grid_remove()
            self._watch_sync_top_visible = False
        elif self._downloads_visible:
            self._downloads_frame.grid_remove()
            self._downloads_visible = False
        elif self._stats_visible:
            self._stats_frame.grid_remove()
            self._stats_visible = False
        else:
            self._files_frame.grid_remove()

        if view_key == "files":
            self._files_frame.grid(row=0, column=0, sticky="nsew")
            self._sync_favorites_from_ftp()
            self._sync_reservations_from_ftp()
        elif view_key == "missing_ep":
            self._missing_ep_frame.grid(row=0, column=0, sticky="nsew")
            self._missing_ep_visible = True
            self._sync_favorites_from_ftp()
            self._sync_shared_dub_verdicts_from_ftp()
            self._sync_missing_episodes_from_ftp()
        elif view_key == "movies":
            self._movies_frame.grid(row=0, column=0, sticky="nsew")
            self._movies_visible = True
            self._sync_favorites_from_ftp()
            self._sync_missing_movies_from_ftp()
        elif view_key == "history":
            self._history_frame.grid(row=0, column=0, sticky="nsew")
            self._history_visible = True
            self._sync_activity_history_from_ftp()
            self._refresh_history_view()   # por si hay subidas nuevas desde la última vez
        elif view_key == "cleanup":
            self._cleanup_frame.grid(row=0, column=0, sticky="nsew")
            self._cleanup_visible = True
            self._sync_favorites_from_ftp()
            self._sync_reservations_from_ftp()
            self._sync_cleanup_candidates_from_ftp()
        elif view_key == "protected":
            self._protected_frame.grid(row=0, column=0, sticky="nsew")
            self._protected_visible = True
            self._render_protected_table()   # con lo que haya en el mirror local, sin esperar al FTP
            self._sync_reservations_from_ftp()
        elif view_key == "watch_sync":
            self._watch_sync_top_frame.grid(row=0, column=0, sticky="nsew")
            self._watch_sync_top_visible = True
            self._refresh_watch_sync_history_view()   # por si hay sincronizaciones nuevas desde la última vez
        elif view_key == "downloads":
            self._downloads_frame.grid(row=0, column=0, sticky="nsew")
            self._downloads_visible = True
        elif view_key == "stats":
            self._stats_frame.grid(row=0, column=0, sticky="nsew")
            self._stats_visible = True
            self._sync_activity_history_from_ftp()
            self._sync_upload_stats_from_ftp()
            self._sync_category_stats_from_ftp()
            self._sync_deletion_stats_from_ftp()
            self._sync_category_upload_stats_from_ftp()
            self._stats_view.refresh_from_cache()
        elif view_key == "config":
            if not self._config_panel_built:
                # Construcción diferida hasta la primera visita real --
                # ver el comentario en _build_ui sobre por qué. Un pequeño
                # respiro visible aquí (la app ya está abierta y en uso)
                # es preferible al mismo coste escondido en cada arranque.
                self._build_config_panel(self._config_panel_frame)
                self._config_panel_built = True
            self._config_panel_frame.grid(row=0, column=0, sticky="nsew")
            self._config_visible = True
            self._save_settings_btn.grid()
            self._schedule_header_layout_check()

        self._nav_segmented.set(self._NAV_LABELS[view_key])
        self._update_status_bar()   # el texto de la derecha depende de la vista activa (ver _update_status_bar)

    def _build_files_tab(self, parent):
        parent.grid_columnconfigure(0, weight=1)
        parent.grid_rowconfigure(0, weight=1)

        body = ctk.CTkFrame(parent, fg_color="transparent")
        body.grid(row=0, column=0, sticky="nsew")
        # Columna 0: tabla de archivos (se expande). Columna 1: separador
        # arrastrable. Columna 2: panel "Buscar en TMDB" (ancho fijo, pero
        # ajustable a mano) -- al arrastrar el separador, la tabla se
        # ensancha o se estrecha sola porque es la única columna con peso.
        body.grid_columnconfigure(0, weight=1)
        body.grid_columnconfigure(1, weight=0)
        body.grid_columnconfigure(2, weight=0)
        body.grid_rowconfigure(1, weight=1)

        # Barra de título de la tabla: el propio label_text="Archivos" del
        # CTkScrollableFrame se desactiva (label_text="") para no duplicar
        # el título — esta barra hace también de título, con los botones de
        # gestión de archivos integrados en ella en vez de en un toolbar
        # aparte por encima de la tabla. Tono distinto (mismo gris que las
        # tarjetas de categoría en Ajustes) para diferenciarla del resto.
        # Grid a 3 columnas con las dos exteriores en el mismo grupo
        # "uniform": así se fuerza el mismo ancho en las dos aunque el
        # contenido de cada lado pese distinto (2 botones vs. 3) -- con
        # weight igual pero sin uniform, cada columna solo iguala el
        # ancho SOBRANTE, no el mínimo de partida, y el título queda
        # descentrado hacia el lado con menos botones.
        table_header = ctk.CTkFrame(body, fg_color=("gray90", "gray20"), corner_radius=8)
        table_header.grid(row=0, column=0, sticky="ew", padx=(0, CONTAINER_GAP), pady=(0, CONTAINER_GAP))
        table_header.grid_columnconfigure(0, weight=1, uniform="header_sides")
        table_header.grid_columnconfigure(1, weight=0)
        table_header.grid_columnconfigure(2, weight=1, uniform="header_sides")

        left_fr = ctk.CTkFrame(table_header, fg_color="transparent")
        left_fr.grid(row=0, column=0, sticky="w")
        # Un tooltip POR BOTÓN, no sobre left_fr/right_fr: puesto en el frame
        # se dispara igual estés sobre el botón que sea, así que "+ Archivos"
        # y "+ Carpeta" enseñaban los dos el texto de la carpeta (y los tres
        # de la derecha, el mismo de los tres, el primero que se registrara).
        add_files_btn = ctk.CTkButton(left_fr, text="+ Archivos", command=self._add_files,
                      fg_color=ACCENT, hover_color=ACCENT_HOVER, width=110)
        attach_tooltip(add_files_btn, lambda: "Añadir archivos sueltos a la lista. Los .zip, .7z, "
                       ".rar y .tar se descomprimen solos, incluidos los anidados.")
        add_files_btn.pack(side="left", padx=(12, 4), pady=8)
        add_folder_btn = ctk.CTkButton(left_fr, text="+ Carpeta", command=self._add_folder,
                      width=100)
        attach_tooltip(add_folder_btn, lambda: "Añadir una carpeta entera, con sus subcarpetas. "
                       "Los comprimidos que encuentre se descomprimen solos. Si detecta 2 o más "
                       "libros/cómics pregunta si son de la misma colección, para identificarlos "
                       "de una sola búsqueda en vez de uno a uno.")
        add_folder_btn.pack(side="left", padx=(0, 4), pady=8)
        # Selecciona/deselecciona TODOS los archivos de la lista (todas las
        # páginas, no solo la visible -- self._multi_selected no depende de
        # qué página esté a la vista, ver _select_range/_current_selection)
        # de golpe, para poder "Asignar a la selección" sobre cientos de
        # capítulos sin tener que Ctrl/Shift+clic página por página.
        self._select_all_btn = ctk.CTkButton(
            left_fr, text="Seleccionar todos", command=self._toggle_select_all,
            fg_color="transparent", border_width=1, width=140)
        self._select_all_btn.pack(side="left", padx=(0, 4), pady=8)
        attach_tooltip(self._select_all_btn, lambda: "Selecciona todos los archivos de todas las páginas de la tabla, "
                      "no solo las visibles. Permite aplicar el mismo resultado de búsqueda/o identificación a cientos de archivos de golpe "
                      "para luego asignarlos todos de una vez con el botón 'Asignar a la selección'.")

        ctk.CTkLabel(table_header, text="Archivos", font=ctk.CTkFont(size=14, weight="bold")).grid(
            row=0, column=1, padx=16, pady=8)

        right_fr = ctk.CTkFrame(table_header, fg_color="transparent")
        right_fr.grid(row=0, column=2, sticky="e")
        # Derecha: Subir todo/seleccionados, Limpiar/seleccionados (pack right inverso)
        # Renombrar eliminado: Asignar ya renombra (ver build_new_name), no tiene sentido duplicado.
        self._upload_all_btn = ctk.CTkButton(right_fr, text="Subir todo", command=self._on_header_upload_clicked,
                      width=130)
        attach_tooltip(self._upload_all_btn, lambda: "Subir al servidor todos los archivos de la lista, "
                       "cada uno a la carpeta de su columna \"Destino\". Respeta el límite de "
                       "subidas simultáneas y el renombrado configurados en Ajustes.")
        self._upload_all_btn.pack(side="right", padx=(4, 12), pady=8)
        self._clear_files_btn = ctk.CTkButton(right_fr, text="Limpiar", command=self._on_header_clear_clicked,
                      fg_color="transparent", border_width=1, width=110)
        attach_tooltip(self._clear_files_btn, lambda: "Vaciar la lista. Los archivos siguen en tu disco "
                       "y en el historial: solo desaparecen de esta tabla.")
        self._clear_files_btn.pack(side="right", padx=4, pady=8)

        # Fuentes compartidas por las columnas truncadas — se reutilizan tanto para
        # dibujar el texto como para medirlo en _fit_text, así ambos ancho coinciden.
        self._font_name = ctk.CTkFont(size=12)
        self._font_det  = ctk.CTkFont(size=11)
        self._font_nn   = ctk.CTkFont(size=11)
        # Igual que las de arriba -- compartidas para no crear un CTkFont
        # nuevo (llamada a Tcl) por cada fila y cada botón de cada fila;
        # con cientos de archivos, esto se notaba en la velocidad de
        # dibujado de la tabla entera.
        self._font_btn   = ctk.CTkFont(size=12)   # botones ▲/▶/✕ de cada fila
        self._font_small = ctk.CTkFont(size=11)   # columnas Estado y Vel.

        # TableView: mismo componente que Episodios/Liberar espacio/
        # Historial (ver gui/table_view.py) -- cabecera fija con los
        # mismos anchos que leen las filas. name/det/nn se recalculan
        # según el ancho disponible (ver _compute_cw/_on_table_resize,
        # comportamiento propio de esta tabla, no del componente).
        sw0 = self._saved_col_widths("archivos")   # anchos guardados de una sesión anterior, si hay
        cw0 = self._compute_cw(dest_w=sw0.get("dest", 140),
                               hidden=self._saved_hidden_columns("archivos"))
        self._col_widths = cw0   # mirror de self._file_table para el código de filas -- ver _apply_col_widths
        self._file_table = TableView(body, columns=[
            ColumnSpec("name", "Nombre original", width=sw0.get("name", cw0["name"]), min_width=80,
                       resizable=True, sortable=True),
            ColumnSpec("det", "Detectado", width=sw0.get("det", cw0["det"]), min_width=55,
                       resizable=True, sortable=True),
            ColumnSpec("nn", "Nuevo nombre", width=cw0["nn"], expand=True, resizable=True, sortable=True),
            ColumnSpec("dest", "Destino", width=sw0.get("dest", 140), min_width=60,
                       resizable=True, sortable=True),
            ColumnSpec("stat", "Estado", width=sw0.get("stat", 74), min_width=50,
                       resizable=True, sortable=True),
            ColumnSpec("bar", "Subida FTP", width=sw0.get("bar", 110), min_width=50, resizable=True),
            ColumnSpec("spd", "Vel.", width=sw0.get("spd", 80), min_width=50, resizable=True),
            ColumnSpec("size", "Peso", width=sw0.get("size", 60), min_width=40, sortable=True),
            # logo/fav/lock/btns: columnas de acción (iconos/botones), no
            # de datos -- no aparecen en el menú contextual de ocultar.
            ColumnSpec("logo", "", width=24, hideable=False),
            ColumnSpec("fav", "", width=28, hideable=False),
            ColumnSpec("lock", "", width=28, hideable=False),
            ColumnSpec("auto", "", width=28, hideable=False),
            ColumnSpec("btns", "", width=28 * 3 + 6, hideable=False),
        ], header_right_pad=16,   # ver TableView.__init__ -- medido a mano contra esta tabla en concreto
        on_visibility_changed=self._on_file_table_visibility_changed)
        self._file_table.grid(row=1, column=0, sticky="nsew", padx=(0, CONTAINER_GAP))
        self._file_table.on_column_resize = self._apply_col_widths
        self._file_table.on_widths_changed = lambda w: self._save_table_col_widths("archivos", w)
        self._file_table.on_header_click = self._on_files_header_click
        self._file_table.set_hidden(self._saved_hidden_columns("archivos"), notify=False)
        # Alias -- el resto de la app (drag&drop, _refresh_table, etc.)
        # ya usaba self._file_list_frame como el contenedor con scroll de
        # las filas; TableView.body es justo eso.
        self._file_list_frame = self._file_table.body

        # Enlazar redimensionado adaptativo al canvas interno del CTkScrollableFrame
        # add="+" preserva el binding nativo _fit_frame_dimensions_to_canvas de CTkScrollableFrame
        # que ajusta el ancho del frame interno al canvas; sin él las filas no llenan el ancho completo
        self._file_list_frame._parent_canvas.bind(
            "<Configure>", self._on_table_resize, add="+")
        self._file_table.enable_dynamic_page_size(lambda _size: self._refresh_table())
        self._file_rows = []
        # tmdb_id -> [etiquetas "⚡" de la tabla de Archivos]. Es una LISTA y no
        # un widget suelto (como en Episodios que faltan) porque aquí puede
        # haber varios archivos de la misma serie a la vez, y al activar el
        # autocompletado tienen que encenderse todos.
        self._file_auto_widgets = {}
        self._files_page = 0
        self._table_resize_debounce_id = None   # ver _on_table_resize
        self._files_sort_key, self._files_sort_asc = self._saved_table_sort(
            "archivos", None, True)   # ver _on_files_header_click -- sin ordenar hasta que se pulse una cabecera
        self._files_table_sort_applied = False   # orden guardado aún no aplicado a self.files (ver _apply_persisted_sort)
        self._apply_col_widths()   # sincroniza self._col_widths con los anchos guardados (sw0), si había

        # Paginado (ver TableView.page_size, calculado dinámicamente según
        # el alto disponible -- ver enable_dynamic_page_size arriba) --
        # mismo motivo y mismo patrón que Episodios/Liberar espacio/
        # Historial: con muchos archivos en cola (auto-watcher llevando un
        # rato, o una carpeta grande arrastrada de golpe) dibujar todas las
        # filas a la vez obliga a hacer scroll dentro de la ventana en vez
        # de solo dentro de la tabla, y con cientos de filas se acerca al
        # límite de objetos GUI de Windows (ver
        # [[project_pagination_user_object_limit]]). Debajo de la tabla,
        # centrada (sin sticky="ew", la columna 0 de "body" ya tiene
        # weight=1).
        files_nav_fr = ctk.CTkFrame(body, fg_color="transparent")
        files_nav_fr.grid(row=2, column=0, pady=(6, 0))
        self._files_prev_btn = ctk.CTkButton(
            files_nav_fr, text="< Anterior", width=100, fg_color="transparent", border_width=1,
            command=lambda: self._files_change_page(-1))
        self._files_prev_btn.pack(side="left")
        self._files_page_lbl = ctk.CTkLabel(files_nav_fr, text="", text_color=PENDING_COLOR)
        self._files_page_lbl.pack(side="left", padx=12)
        self._files_next_btn = ctk.CTkButton(
            files_nav_fr, text="Siguiente >", width=100, fg_color="transparent", border_width=1,
            command=lambda: self._files_change_page(1))
        self._files_next_btn.pack(side="left")

        self._drop_zone = ctk.CTkLabel(self._file_list_frame,
                                        text="Arrastra archivos aquí\no usa + Archivos",
                                        font=ctk.CTkFont(size=15), text_color=PENDING_COLOR, height=200)
        self._drop_zone.pack(pady=40)

        # Separador arrastrable entre la tabla y el panel de TMDB -- mismo
        # patrón visual que los separadores de columna de TableView (ver
        # gui/table_view.py), pero independiente de esos (ajusta el ancho
        # del panel, no columnas de la tabla).
        self._detail_sash = tk.Frame(body, width=4, bg="#505060",
                                      cursor="sb_h_double_arrow")
        self._detail_sash.grid(row=0, column=1, rowspan=2, sticky="ns", pady=8)
        self._detail_sash.bind("<ButtonPress-1>", self._detail_sash_press)
        self._detail_sash.bind("<B1-Motion>", self._detail_sash_motion)
        self._detail_sash.bind("<ButtonRelease-1>", self._detail_sash_release)
        self._detail_sash_state = None
        self._detail_resize_debounce_id = None
        self._detail_panel_width = 255   # igual que el width= inicial de _build_detail_panel

        self._detail_panel = self._build_detail_panel(body)
        self._detail_panel.grid(row=0, column=2, rowspan=2, sticky="nsew")

        # Drag & drop — registrar la ventana entera como destino
        if _DND_AVAILABLE:
            self.drop_target_register(DND_FILES)
            self.dnd_bind("<<Drop>>", self._on_drop)

    def _saved_col_widths(self, table_id: str) -> dict:
        """Anchos de columna guardados para una tabla (ver
        _save_table_col_widths) -- {} si nunca se guardó nada, p.ej. en el
        primer arranque o tras un reset de configuración."""
        return dict(self.config_data.get("table_col_widths", {}).get(table_id, {}))

    def _save_table_col_widths(self, table_id: str, widths: dict):
        """Callback de TableView.on_widths_changed: se guarda en disco
        inmediatamente al soltar un separador (no espera a "Guardar
        configuración"), como pidió el usuario."""
        all_saved = dict(self.config_data.get("table_col_widths", {}))
        all_saved[table_id] = widths
        self.config_data.set("table_col_widths", all_saved)
        self.config_data.save()

    def _saved_hidden_columns(self, table_id: str) -> set:
        """Columnas ocultas guardadas para una tabla (ver
        _save_hidden_columns) -- vacío si nunca se guardó nada."""
        return set(self.config_data.get("table_hidden_columns", {}).get(table_id, []))

    def _save_hidden_columns(self, table_id: str, hidden: set):
        """Callback de TableView.on_visibility_changed: se guarda en disco
        en cuanto el usuario oculta/muestra una columna (no espera a
        "Guardar configuración"), igual que los anchos de columna."""
        all_saved = dict(self.config_data.get("table_hidden_columns", {}))
        all_saved[table_id] = sorted(hidden)
        self.config_data.set("table_hidden_columns", all_saved)
        self.config_data.save()

    def _saved_table_sort(self, table_id: str, default_key=None, default_asc=True):
        """Orden de columna guardado para una tabla (ver _save_table_sort) --
        (clave, ascendente) o el par por defecto si la tabla nunca se
        ordenó / no hay nada guardado (primer arranque o reset de config)."""
        saved = self.config_data.get("table_sort", {}).get(table_id)
        if isinstance(saved, dict) and "key" in saved:
            return saved.get("key"), bool(saved.get("asc", default_asc))
        return default_key, default_asc

    def _save_table_sort(self, table_id: str, key, asc: bool):
        """Callback de los handlers de clic en cabecera: guarda el orden
        elegido en disco al instante (no espera a "Guardar configuración"),
        para que el orden de columnas elegido persista entre sesiones."""
        all_saved = dict(self.config_data.get("table_sort", {}))
        all_saved[table_id] = {"key": key, "asc": bool(asc)}
        self.config_data.set("table_sort", all_saved)
        self.config_data.save()

    def _compute_cw(self, avail_w=None, dest_w=140, name_w=None, det_w=None,
                     stat_w=None, bar_w=None, spd_w=None, hidden=()):
        """Calcula anchos de columna adaptativos. avail_w = px disponibles en la tabla.
        FIXED incluye los 6 sashes de 4px + padx de botones (4+2+2+2) = 30px constantes,
        más la columna "Destino" y su separador (4px). "Destino" SÍ tiene
        sash (ColumnSpec resizable=True) y su ancho se guarda entre
        sesiones -- dest_w debe ser el ancho REAL actual (guardado o
        arrastrado a mano), nunca un 140 fijo: si el usuario ensanchó
        "Destino" y luego solo redimensiona la ventana (_on_table_resize),
        recalcular "Nuevo nombre" asumiendo 140 aquí le daba más espacio
        flexible del que en realidad quedaba libre, así que el texto se
        truncaba con un ancho mayor del que la columna ocupa de verdad en
        pantalla -- se salía visualmente en vez de cortarse con "…".
        28*5 (no *3): 5 botones por fila -- favorito, reservar, subir,
        reproducir, quitar -- desde que se añadieron favorito y reservar;
        cada uno de esos dos añade su propio padx aparte de los 30px de
        los tres originales (ver fav_btn/lock_btn.pack en _refresh_table).
        +24+4: logo de Jellyfin/Plex ("Abrir en Jellyfin/Plex", ver
        _open_entry_in_media_server), mismo tamaño que en Liberar espacio.

        name_w/det_w/stat_w/bar_w/spd_w: si se dan (ver _on_table_resize),
        se usan TAL CUAL en vez de recalcularse -- name/det/stat/bar/spd
        son TODAS resizable=True (el usuario puede arrastrar su propio
        sash, y ese ancho se guarda entre sesiones, ver sw0 en
        _build_files_tab), igual que Destino. Antes, CUALQUIER <Configure>
        del canvas (típicamente el primero, nada más mapearse la ventana
        al arrancar, o cualquier redimensionado normal de la ventana
        después) recalculaba name/det con la fórmula de abajo y machacaba
        en silencio lo que el usuario hubiera ensanchado a mano -- bug
        real: "ensancho 'Nombre original' para ver nombres largos,
        reinicio la app y vuelve a su ancho de antes". Ese mismo arreglo
        (pasar el ancho REAL en vez de recalcularlo) se aplicó a name/det/
        dest pero no a stat/bar/spd, que se quedaron como constantes fijas
        (74/110/80) en FIXED aunque también tienen sash -- así, ensanchar
        "Estado"/"Subida FTP"/"Vel." a mano y luego redimensionar la
        ventana calculaba "Nuevo nombre" con MÁS espacio del que en
        realidad quedaba libre (siguiendo asumiendo el ancho pequeño por
        defecto de esas tres columnas), así que la fila entera se pasaba
        del ancho visible de la tabla -- lo que se veía "cortado" por el
        borde derecho eran los botones (▲▶✕, favorito, candado), que van
        al final de la fila, después de "Nuevo nombre". Solo se recalculan
        desde cero (parámetro en None) la primera vez que se construye la
        tabla, antes de que exista ningún ancho guardado/arrastrado que
        respetar.

        hidden: claves de columnas ocultas (menú contextual de la
        cabecera, ver TableView.set_hidden) -- su ancho no se cuenta en
        FIXED, para que el espacio flexible (name/det/nn) se reparta entre
        las columnas que de verdad se ven. Antes de soportar columnas
        ocultas, si ocultabas p.ej. "Subida FTP" (110px) el flex seguía
        descontando esos 110px que ya nadie ocupaba, y name/det/nn se
        quedaban más estrechos de lo necesario (texto truncado antes de
        tiempo)."""
        hidden = set(hidden)
        FIXED = 0
        if "stat" not in hidden:
            FIXED += stat_w if stat_w is not None else 74
        if "bar" not in hidden:
            FIXED += bar_w if bar_w is not None else 110
        if "spd" not in hidden:
            FIXED += spd_w if spd_w is not None else 80
        if "size" not in hidden:
            FIXED += 60
        if "logo" not in hidden:
            FIXED += 24
        FIXED += 28*5   # fav/lock/btns -- columnas de acción, no ocultables
        if "dest" not in hidden:
            FIXED += dest_w
        FIXED += 4 + 4 + 4 + 30 + 4  # widgets fijos + spacing constante
        PAD   = 16                           # padding interno CTkScrollableFrame
        if avail_w is None:
            avail_w = 900
        flex = max(0, avail_w - FIXED - PAD)
        if name_w is None:
            name = max(80, int(flex * 0.26))
            det  = max(55, int(flex * 0.12))
        else:
            name, det = name_w, det_w
        nn = max(0, flex - name - det)
        return dict(name=name, det=det, nn=nn, dest=dest_w,
                    stat=stat_w if stat_w is not None else 74,
                    bar=bar_w if bar_w is not None else 110,
                    spd=spd_w if spd_w is not None else 80,
                    size=60, btn=28, logo=24)

    _TABLE_RESIZE_DEBOUNCE_MS = 150   # ver _on_table_resize

    def _on_table_resize(self, event):
        """Reajusta las columnas al cambiar el ancho del canvas.

        Toda la aritmética vive ahora en TableView.fit_to_width (que conoce
        anchos, paddings y mínimos reales de cada columna) en vez de en la
        fórmula de _compute_cw, que llevaba una lista de constantes a mano
        ("74 + 110 + 80 + ...") y había que acordarse de actualizar cada vez
        que una columna cambiaba de ancho por defecto o se volvía
        arrastrable -- olvidarlo era justo lo que dejaba la fila más ancha
        que la tabla y escondía los botones del final por la derecha.
        fit_to_width encoge las columnas arrastrables solo lo necesario (sin
        bajar de su mínimo) y las devuelve a su ancho elegido en cuanto
        vuelve a haber sitio."""
        prev_nn = self._col_widths.get("nn")
        changed = self._file_table.fit_to_width(event.width)
        if not changed and self._file_table.col_width("nn") == prev_nn:
            return
        # _apply_col_widths() (el reflow caro: font.measure() + varios
        # .configure() POR FILA visible) se aplaza con antirrebote -- este
        # handler se dispara en CADA píxel mientras se arrastra el
        # separador del panel lateral (la columna de la tabla tiene
        # weight=1, así que se redimensiona en cascada), y sin frenarlo
        # eran cientos de llamadas Tcl por evento de ratón, el origen real
        # del tirón al arrastrar. Los anchos de columna/cabecera de arriba
        # sí se quedan síncronos -- eso es barato y se ve en vivo durante
        # el arrastre.
        if self._table_resize_debounce_id is not None:
            self.after_cancel(self._table_resize_debounce_id)
        self._table_resize_debounce_id = self.after(
            self._TABLE_RESIZE_DEBOUNCE_MS, self._apply_col_widths_debounced)

    def _on_file_table_visibility_changed(self):
        """Callback de TableView.on_visibility_changed (menú contextual de
        la cabecera): redibuja las filas con las columnas ocultas quitadas
        y persiste el estado, igual que hacen los anchos de columna."""
        self._refresh_table()
        self._save_hidden_columns("archivos", self._file_table.hidden_columns())

    def _apply_col_widths_debounced(self):
        self._table_resize_debounce_id = None
        self._apply_col_widths()

    def _apply_col_widths(self):
        """Sincroniza self._col_widths desde self._file_table (que es la
        fuente real de los anchos, ver TableView.set_width/col_width) y
        actualiza las filas ya pintadas -- se llama tanto tras
        _on_table_resize como tras arrastrar un separador a mano (ver
        self._file_table.on_column_resize).

        Ya NO toca el ancho de ningún widget: el ancho lo tiene la celda
        que envuelve a cada etiqueta (TableView.cell), y de reajustarlas se
        encarga el propio componente (_apply_cell_widths, llamado desde
        set_width/_sash_motion). Aquí solo se vuelve a recortar el TEXTO
        para que el "…" caiga donde toca con el ancho nuevo -- puramente
        cosmético: si se quedara corto o largo, la celda lo recorta igual y
        la tabla no se descuadra."""
        for key in ("name", "det", "nn", "dest", "stat", "bar", "spd", "size"):
            self._col_widths[key] = self._file_table.col_width(key)
        cw = self._col_widths
        for row in self._file_rows:
            if row["name"] is not None:
                row["name"].configure(
                    text=_fit_text(row.get("_raw_name", ""), cw["name"], self._font_name))
            if row["detected"] is not None:
                row["detected"].configure(
                    text=_fit_text(row.get("_raw_det", ""), cw["det"], self._font_det))
            if row["new_name"] is not None:
                row["new_name"].configure(
                    text=_fit_text(row["entry"].new_name, cw["nn"], self._font_nn))
            if row["dest"] is not None:
                row["dest"].configure(
                    text=_fit_text(self._preview_remote_path(row["entry"]), cw["dest"], self._font_det))

    _DETAIL_PANEL_MIN_W = 180
    _DETAIL_PANEL_MAX_W = 500
    _DETAIL_RESIZE_DEBOUNCE_MS = 150

    def _detail_sash_press(self, event):
        self._detail_sash_state = {"x0": event.x_root, "w0": self._detail_panel_width}

    def _detail_sash_motion(self, event):
        if not self._detail_sash_state:
            return
        # El panel está a la derecha del separador: arrastrar hacia la
        # izquierda (x decrece) lo ensancha, hacia la derecha lo estrecha.
        delta = self._detail_sash_state["x0"] - event.x_root
        new_w = max(self._DETAIL_PANEL_MIN_W,
                    min(self._DETAIL_PANEL_MAX_W, self._detail_sash_state["w0"] + delta))
        if new_w == self._detail_panel_width:
            return   # mismo ancho (redondeo) -- no repetir trabajo de layout
        self._detail_panel_width = new_w
        # Durante el arrastre en vivo SOLO se mueve el borde del panel
        # (barato, ~1ms) -- reconfigurar el ancho de un CTkTextbox es caro
        # de por sí (~20-30ms cada uno, es un widget compuesto con canvas +
        # scrollbar interno), y hacerlo en cada píxel de movimiento del
        # ratón resultaba muy lento. El reajuste completo de los cuadros de
        # texto se aplaza con antirrebote: solo se hace de verdad cuando el
        # arrastre se detiene un momento o se suelta el botón.
        self._detail_panel.configure(width=new_w)
        if self._detail_resize_debounce_id is not None:
            self.after_cancel(self._detail_resize_debounce_id)
        self._detail_resize_debounce_id = self.after(
            self._DETAIL_RESIZE_DEBOUNCE_MS, self._commit_detail_panel_width)

    def _detail_sash_release(self, event):
        self._detail_sash_state = None
        if self._detail_resize_debounce_id is not None:
            self.after_cancel(self._detail_resize_debounce_id)
            self._detail_resize_debounce_id = None
        self._commit_detail_panel_width()

    def _commit_detail_panel_width(self):
        """Aplica self._detail_panel_width de verdad a los widgets de texto
        de dentro del panel (el póster se queda a tamaño fijo -- es una
        imagen ya renderizada a una resolución concreta, no se puede
        reescalar solo cambiando el ancho declarado del widget sin perder
        calidad). Es la parte cara (ver _detail_sash_motion) -- se llama con
        antirrebote durante el arrastre, no en cada evento de movimiento."""
        self._detail_resize_debounce_id = None
        w = self._detail_panel_width
        self._detail_panel.configure(width=w)
        content_w = max(100, w - 40)   # descontar el padding interno del panel
        self._detail_title.configure(width=content_w)
        self._detail_episode.configure(wraplength=content_w)
        self._detail_meta.configure(width=content_w)
        self._detail_cert.configure(width=content_w)
        self._detail_cast.configure(width=content_w)
        self._detail_overview.configure(width=content_w)
        self._detail_error.configure(width=content_w)
        self._detail_ftp_path_lbl.configure(wraplength=content_w)
        self._detail_ftp_tree_box.configure(width=content_w)
        # El wrap cambia con el ancho, así que el número de líneas (y por
        # tanto el alto que necesitan) también cambia.
        self._autosize_textbox(self._detail_title)
        self._autosize_textbox(self._detail_meta)
        self._autosize_textbox(self._detail_cert)
        self._autosize_textbox(self._detail_cast)
        self._autosize_textbox(self._detail_overview)
        self._autosize_textbox(self._detail_error)

    @staticmethod
    def _make_uk_flag_image(w=20, h=14):
        """Bandera del Reino Unido dibujada a mano con PIL (simplificada,
        sin pretensión de exactitud heráldica) -- ver _build_detail_panel
        para por qué no se usa el emoji 🇬🇧."""
        img = Image.new("RGB", (w, h), (0, 36, 125))          # azul marino
        draw = ImageDraw.Draw(img)
        draw.line([(0, 0), (w, h)], fill=(255, 255, 255), width=3)     # aspas blancas
        draw.line([(0, h), (w, 0)], fill=(255, 255, 255), width=3)
        draw.line([(0, 0), (w, h)], fill=(200, 16, 46), width=1)       # aspas rojas, más finas
        draw.line([(0, h), (w, 0)], fill=(200, 16, 46), width=1)
        draw.rectangle([0, h // 2 - 3, w, h // 2 + 2], fill=(255, 255, 255))   # cruz blanca
        draw.rectangle([w // 2 - 3, 0, w // 2 + 2, h], fill=(255, 255, 255))
        draw.rectangle([0, h // 2 - 1, w, h // 2 + 1], fill=(200, 16, 46))     # cruz roja
        draw.rectangle([w // 2 - 1, 0, w // 2 + 1, h], fill=(200, 16, 46))
        return img

    def _build_detail_panel(self, parent):
        panel = ctk.CTkFrame(parent, width=255)
        panel.grid_propagate(False)
        panel.grid_rowconfigure(1, weight=1)
        panel.grid_columnconfigure(0, weight=1)

        # -- Zona superior: busqueda (siempre visible) --
        search_top = ctk.CTkFrame(panel, fg_color="transparent")
        search_top.grid(row=0, column=0, sticky="ew", padx=8, pady=(10, 4))
        search_top.columnconfigure(0, weight=1)

        search_label_row = ctk.CTkFrame(search_top, fg_color="transparent")
        search_label_row.grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 2))
        self._search_label = ctk.CTkLabel(search_label_row, text="Buscar en TMDB:",
                     font=ctk.CTkFont(size=11), anchor="w")
        self._search_label.pack(side="left")
        # Bandera del Reino Unido -- indica que ComicVine hay que buscarlo
        # en inglés (ver core/comicvine_client.py, project_comicvine_original_
        # title_search en memoria). Dibujada con PIL en vez de un emoji de
        # bandera (🇬🇧): los emoji de bandera son secuencias de dos
        # "regional indicator" que Tk no compone en este sistema -- se ven
        # como un recuadro/letras sueltas en vez de una bandera (mismo tipo
        # de artefacto ya visto con ▶◀▼, ver memoria del proyecto).
        self._uk_flag_image = ctk.CTkImage(self._make_uk_flag_image(), size=(20, 14))
        self._search_lang_flag = ctk.CTkLabel(search_label_row, image=self._uk_flag_image, text="")
        self._search_lang_flag.pack(side="left", padx=(5, 0))
        self._search_lang_flag.pack_forget()   # oculta salvo para cómics -- ver _reset_search_panel
        # Selector manual de con qué servicio buscar -- "Auto" (por defecto,
        # cadena automática de siempre según entry.is_comic/is_book) o
        # forzar uno concreto sin restricción de tipo (p.ej. AniList en un
        # .epub) -- útil sobre todo para manga, que ComicVine identifica mal
        # a menudo incluso con traducción vía IA (ver
        # self._search_provider_override/_on_search_provider_changed). Solo
        # afecta a la búsqueda MANUAL de este panel -- ni la identificación
        # automática al añadir archivos ni el Modo Automático la usan.
        self._SEARCH_PROVIDER_LABELS = {
            "tmdb": "TMDB", "openlibrary": "OpenLibrary", "google_books": "GoogleBooks",
            "comicvine": "ComicVine", "mangadex": "MangaDex", "anilist": "AniList", "kitsu": "Kitsu",
        }
        self._search_provider_override = "tmdb"
        self._search_provider_menu = ctk.CTkOptionMenu(
            search_top, values=list(self._SEARCH_PROVIDER_LABELS.values()),
            command=self._on_search_provider_changed, width=239, height=22,
            font=ctk.CTkFont(size=11))
        self._search_provider_menu.set("TMDB")
        self._search_provider_menu.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(0, 4))
        # Un único campo hace de buscador y de desplegable de resultados:
        # se escribe el título y se pulsa Enter/"Buscar", y el propio campo
        # se convierte en el desplegable para elegir entre los resultados
        # (antes eran dos widgets separados — un CTkEntry para buscar y un
        # CTkComboBox aparte para el resultado). Elegir un resultado del
        # desplegable solo lo PREVISUALIZA (póster, sinopsis...) — no se
        # aplica a la entrada hasta pulsar "Asignar".
        # dropdown_font: el desplegable es un menú nativo del SO que se
        # autoajusta solo al título más largo que se le pase (no al ancho
        # del campo de texto) -- por eso ya no hace falta recortar las
        # etiquetas antes de pasarlas, ver _apply_search_results.
        self._search_dropdown_font = ctk.CTkFont()
        self._result_combo = ctk.CTkComboBox(search_top, values=[],
                                              command=self._on_result_preview,
                                              dropdown_font=self._search_dropdown_font)
        self._result_combo.set("")
        self._result_combo.grid(row=2, column=0, sticky="ew")
        self._result_combo.bind("<Return>", lambda _: self._manual_search(use_ai_fallback=True))
        # Búsqueda automática mientras se escribe (con un pequeño retardo
        # para no lanzar una petición a TMDB en cada pulsación).
        self._result_combo.bind("<KeyRelease>", self._on_search_key_release)
        # Flechas arriba/abajo: recorren los resultados ya obtenidos con
        # vista previa en vivo (póster/sinopsis/título), sin necesidad de
        # abrir el desplegable -- ver _cycle_search_result.
        self._result_combo.bind("<Down>", lambda e: self._cycle_search_result(1))
        self._result_combo.bind("<Up>", lambda e: self._cycle_search_result(-1))
        self._search_debounce_id = None
        search_btn = ctk.CTkButton(search_top, text="Buscar", width=60,
                      command=lambda: self._manual_search(use_ai_fallback=True))
        attach_tooltip(search_btn, lambda: "Buscar el título escrito arriba en el proveedor "
                       "elegido. Si no encuentra nada, prueba con la IA para limpiar el nombre.")
        search_btn.grid(row=2, column=1, padx=(4, 0))
        # Texto dinámico: "Asignar" con un solo archivo (ancla), "Asignar a
        # la selección (N)" con varios marcados vía Ctrl/Shift+clic -- ver
        # _update_assign_button_label/_current_selection. "Asignar y
        # subir" al lado hace lo mismo y además encola la subida al
        # momento (mismo _upload_one de siempre, ver
        # _assign_selected_result) -- para no tener que pulsar "Asignar" y
        # luego ir a subir el archivo aparte.
        self._assign_btn = ctk.CTkButton(search_top, text="Asignar", width=95,
                      command=self._assign_selected_result)
        attach_tooltip(self._assign_btn, lambda: "Aplicar el resultado que se ve arriba al "
                       "archivo (o a todos los marcados con Ctrl/Mayús+clic). Cada uno conserva "
                       "su propio número de episodio.")
        self._assign_btn.grid(row=3, column=0, sticky="ew", pady=(4, 0), padx=(0, 4))
        self._assign_and_upload_btn = ctk.CTkButton(
            search_top, text="Asignar y subir", width=95,
            command=lambda: self._assign_selected_result(also_upload=True))
        attach_tooltip(self._assign_and_upload_btn, lambda: "Lo mismo que \"Asignar\" y además "
                       "manda el archivo a la cola de subida, sin tener que ir a subirlo aparte.")
        self._assign_and_upload_btn.grid(row=3, column=1, sticky="ew", pady=(4, 0))
        # Solo para cómics (ver _reset_search_panel, que la muestra/oculta
        # al cambiar de selección) -- ComicVine falla casi siempre con el
        # título detectado localmente en castellano, este botón pide a la
        # IA el título original y reintenta (ver _manual_ai_translate_comic).
        self._ai_translate_comic_btn = ctk.CTkButton(
            search_top, text="🪄 IA: título original", width=200,
            fg_color="transparent", border_width=1,
            command=self._manual_ai_translate_comic)
        attach_tooltip(self._ai_translate_comic_btn, lambda: "Pedir a la IA el título ORIGINAL "
                       "(normalmente en inglés) y repetir la búsqueda con él: el catálogo de "
                       "ComicVine casi no tiene títulos en castellano.")
        self._ai_translate_comic_btn.grid(row=4, column=0, columnspan=2, sticky="ew", pady=(4, 0))
        self._ai_translate_comic_btn.grid_remove()
        self._tmdb_results = []
        # Qué cliente produjo self._tmdb_results -- "tmdb" | "book" | "comic"
        # (ver _manual_search_worker) -- necesario porque cada uno devuelve
        # resultados con forma distinta, así que construir el MediaInfo
        # final (_build_info_from_result) o la etiqueta del desplegable
        # (_apply_search_results) tiene que saber a cuál preguntar.
        self._results_kind = "tmdb"
        # Índice del resultado que se ve AHORA MISMO en el panel de
        # detalles (póster, sinopsis...) -- ver _preview_result. "Asignar"
        # lo usa como último recurso si el texto del desplegable no
        # coincide con ningún valor (ver _assign_selected_result): tras
        # buscar, el primer resultado se previsualiza solo, pero el campo
        # se deja con lo que el usuario escribió (para poder seguir
        # afinando la búsqueda) -- sin este índice, "Asignar" no
        # encontraba ninguna coincidencia y no hacía nada, en silencio,
        # aunque la portada y la info YA estuvieran a la vista.
        self._previewed_result_idx = -1

        # -- Zona inferior: detalles con scroll --
        scroll = ctk.CTkScrollableFrame(panel, fg_color="transparent", label_text="")
        scroll.grid(row=1, column=0, sticky="nsew", padx=4, pady=(4, 6))
        scroll.columnconfigure(0, weight=1)

        self._poster_label = ctk.CTkLabel(scroll, text="", width=180, height=220)
        self._poster_label.pack(pady=(4, 2))
        # Imagen 1x1 transparente real -- CTkLabel.configure(image=None) NO
        # limpia una imagen ya puesta (bug de customtkinter 5.2.2::
        # CTkLabel._update_image: si self._image queda en None, ni la rama
        # de CTkImage ni la de "elif self._image is not None" se ejecutan,
        # así que el tkinter.Label interno se queda con la imagen anterior
        # detrás del texto nuevo -- visto de verdad: "Sin carátula" escrito
        # encima de la portada del resultado anterior al cambiar de
        # selección). Pasar esta imagen transparente en vez de None fuerza
        # el borrado real -- ver _set_poster.
        self._blank_poster_image = ctk.CTkImage(
            Image.new("RGBA", (1, 1), (0, 0, 0, 0)), size=(180, 260))
        self._overview_token = None   # token de la carga en curso de sinopsis de OpenLibrary (ver _load_openlibrary_description)
        # Árbol de archivos FTP del panel de detalle -- token PROPIO, no
        # self._poster_token: ese se pone a None (no a un object() nuevo)
        # cuando el resultado no trae póster (ver _apply_overview_and_poster),
        # así que dos selecciones seguidas sin póster dejarían el mismo
        # "token" las dos veces y una respuesta FTP obsoleta no se detectaría
        # como tal. Ver _update_detail_ftp_path_label/_toggle_detail_ftp_tree.
        self._detail_ftp_token = None
        self._detail_ftp_tree_expanded = False
        self._detail_ftp_tree_ruta = None
        self._detail_ftp_tree_loaded_for = None
        # CTkTextbox (no CTkLabel) para el título, la sinopsis y el error: de
        # solo lectura (state="disabled") pero seleccionable y copiable con
        # ratón/teclado, a diferencia de un CTkLabel normal.
        self._detail_title = ctk.CTkTextbox(
            scroll, width=215, height=1, wrap="word",
            font=ctk.CTkFont(size=13, weight="bold"), fg_color="transparent",
            activate_scrollbars=False)
        self._detail_title.configure(state="disabled")
        self._detail_title.pack(pady=(4, 0), fill="x")
        self._detail_episode = ctk.CTkLabel(scroll, text="", wraplength=215,
                                             font=ctk.CTkFont(size=12))
        self._detail_episode.pack()
        self._detail_year = ctk.CTkLabel(scroll, text="", text_color=PENDING_COLOR)
        self._detail_year.pack()
        self._detail_confidence = ctk.CTkLabel(scroll, text="", font=ctk.CTkFont(size=11))
        self._detail_confidence.pack()
        # Categoría (tipo · año · nota · géneros) y clasificación por edad --
        # mismas líneas que el panel lateral de Recomendado, para que el
        # detalle de Archivos muestre la misma información que el resto de
        # pestañas (ver _update_detail/_preview_result).
        self._detail_meta = ctk.CTkTextbox(
            scroll, width=215, height=1, wrap="word",
            font=ctk.CTkFont(size=11), fg_color="transparent",
            activate_scrollbars=False)
        self._detail_meta.configure(state="disabled")
        self._detail_meta.pack(pady=(2, 0), fill="x")
        self._detail_cert = ctk.CTkTextbox(
            scroll, width=215, height=1, wrap="word",
            font=ctk.CTkFont(size=11), fg_color="transparent",
            activate_scrollbars=False)
        self._detail_cert.configure(state="disabled")
        self._detail_cert.pack(pady=(0, 0), fill="x")
        # Reparto -- se pide a TMDB on-demand al seleccionar (ver
        # _load_detail_cast), como la clasificación por edad: no viene en el
        # resultado de búsqueda, hace falta una llamada a /credits.
        self._detail_cast = ctk.CTkTextbox(
            scroll, width=215, height=1, wrap="word",
            font=ctk.CTkFont(size=11), fg_color="transparent",
            text_color=PENDING_COLOR, activate_scrollbars=False)
        self._detail_cast.configure(state="disabled")
        self._detail_cast.pack(pady=(0, 0), fill="x")
        self._detail_overview = ctk.CTkTextbox(
            scroll, width=215, height=1, wrap="word",
            font=ctk.CTkFont(size=11), fg_color="transparent",
            activate_scrollbars=False)
        self._detail_overview.configure(state="disabled")
        self._detail_overview.pack(pady=4, fill="x")
        self._detail_error = ctk.CTkTextbox(
            scroll, width=215, height=1, wrap="word",
            font=ctk.CTkFont(size=11), fg_color="transparent",
            text_color=ERROR_COLOR, activate_scrollbars=False)
        self._detail_error.configure(state="disabled")
        self._detail_error.pack(pady=(0, 4), fill="x")

        # Ruta de la serie/película en el FTP (si ya existe de una subida
        # anterior) -- mismo patrón que el panel de Episodios que faltan:
        # clicable, despliega el árbol de archivos de esa carpeta. Ver
        # _update_detail_ftp_path_label/_toggle_detail_ftp_tree.
        self._detail_ftp_path_lbl = ctk.CTkLabel(
            scroll, text="", font=ctk.CTkFont(size=11), text_color=PENDING_COLOR,
            wraplength=215, justify="left", anchor="w", cursor="hand2")
        self._detail_ftp_path_lbl.pack(pady=(0, 4), fill="x")
        self._detail_ftp_path_lbl.bind("<Button-1>", lambda ev: self._toggle_detail_ftp_tree())

        self._detail_ftp_tree_box = ctk.CTkTextbox(
            scroll, width=215, height=180, wrap="word", font=ctk.CTkFont(size=10))
        self._detail_ftp_tree_box.configure(state="disabled")
        # sin pack -- solo se empaqueta al desplegar (ver _toggle_detail_ftp_tree)

        # Enlaces personalizables (Ajustes > Plantillas, nivel episodio) --
        # un archivo de Archivos es siempre un único episodio/película/
        # emisión, así que usa el mismo nivel que los botones POR EPISODIO
        # de Episodios que faltan (ver _render_detail_links).
        self._detail_links_frame = ctk.CTkFrame(scroll, fg_color="transparent")
        self._detail_links_frame.pack(pady=(0, 4), fill="x")

        return panel

