    def _push_missing_episodes_to_ftp(self):
        """Comparte la caché ACTUAL de "Episodios que faltan" (ver
        core/missing_episodes_cache.py) -- llamado tras cualquier cambio
        local que la deje al día (escaneo completo, reescaneo de una
        serie, quitar un episodio ya subido, quitar una serie borrada).
        Reemplaza la lista compartida entera con lo que hay en local en
        ESE momento, ya sin los campos personales ("ignored"/
        "ai_verdict", ver strip_personal_fields) -- igual que Liberar
        espacio, un resultado local recién actualizado es la fuente más
        fiable posible, no hace falta fusionar nada aquí; la parte
        delicada (no perder aportaciones de otros clientes) ya la cubre
        strip_personal_fields/merge_remote_into_local en el lado de
        aplicar, no en el de subir."""
        remote_path = self._missing_episodes_remote_path()
        if not remote_path:
            return

        def worker():
            from core.missing_episodes_cache import load_cache, strip_personal_fields
            import json as _json
            own_ftp = self._new_ftp_client()
            try:
                ok, _msg = own_ftp.connect(
                    self.config_data.get("ftp_host", ""),
                    int(self.config_data.get("ftp_port", 21)),
                    self.config_data.get("ftp_user", ""),
                    self.config_data.get("ftp_password", ""),
                    self.config_data.get("ftp_use_tls", False))
                if not ok:
                    _log.warning(
                        "Episodios que faltan: no se pudo conectar al FTP para compartir la caché (%s)", _msg)
                    return
                payload = strip_personal_fields(load_cache())
                data = _json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
                up_ok, _up_msg = own_ftp.upload_bytes(data, remote_path)
                if up_ok:
                    _log.info("Episodios que faltan: caché compartida con %d serie(s)",
                              len([k for k in payload if k != "_meta"]))
                else:
                    _log.warning("Episodios que faltan: no se pudo subir la caché compartida (%s)", _up_msg)
            finally:
                own_ftp.disconnect()
        threading.Thread(target=worker, daemon=True).start()

    def _push_missing_movies_to_ftp(self):
        """Comparte la caché ACTUAL de "Películas" (ver
        core/missing_movies_cache.py) -- llamado tras cualquier cambio
        local que la deje al día (una película subida, un escaneo que
        detecta que ya está en el servidor). A diferencia de episodios,
        aquí no se reemplaza la caché remota entera: se hace MERGE con lo
        que ya hubiera publicado otro cliente, conservando los datos de
        cada película (título, cartel, watch...) de la versión más completa
        y combinando el flag "in_server" con OR (si cualquiera de los dos
        clientes dice que la película ya está en su servidor, queda
        marcada como en servidor -- así una instalación cuya biblioteca
        todavía no ha reindexado la película no la "desmarca" para las
        demás)."""
        remote_path = self._missing_movies_remote_path()
        if not remote_path:
            return

        def worker():
            from core.missing_movies_cache import load_cache, merge_movies_cache
            import json as _json
            own_ftp = self._new_ftp_client()
            try:
                ok, _msg = own_ftp.connect(
                    self.config_data.get("ftp_host", ""),
                    int(self.config_data.get("ftp_port", 21)),
                    self.config_data.get("ftp_user", ""),
                    self.config_data.get("ftp_password", ""),
                    self.config_data.get("ftp_use_tls", False))
                if not ok:
                    _log.warning(
                        "Películas: no se pudo conectar al FTP para compartir la caché (%s)", _msg)
                    return
                remote_cache = {}
                raw = own_ftp.download_bytes(remote_path)
                if raw:
                    try:
                        parsed = _json.loads(raw.decode("utf-8"))
                        if isinstance(parsed, dict):
                            remote_cache = parsed
                    except ValueError:
                        remote_cache = {}
                payload = merge_movies_cache(load_cache(), remote_cache)
                data = _json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
                up_ok, _up_msg = own_ftp.upload_bytes(data, remote_path)
                if up_ok:
                    _log.info("Películas: caché compartida con %d película(s)",
                              len([k for k in payload if k != "_meta"]))
                else:
                    _log.warning("Películas: no se pudo subir la caché compartida (%s)", _up_msg)
            finally:
                own_ftp.disconnect()
        threading.Thread(target=worker, daemon=True).start()

    def _apply_synced_missing_episodes(self, remote_cache: dict):
        """Aplica una caché de "Episodios que faltan" ya sincronizada
        (de _sync_missing_episodes_from_ftp) -- fusiona sobre el mirror
        local (conservando "ignored"/"ai_verdict" propios, ver
        merge_remote_into_local), la guarda, y reconstruye
        self._missing_ep_results con la MISMA función que ya usa el
        arranque (_load_missing_episodes_from_cache), para no duplicar
        esa derivación."""
        from core.missing_episodes_cache import load_cache, save_cache, merge_remote_into_local
        previous = load_cache()
        merged = merge_remote_into_local(previous, remote_cache)
        changed = merged != previous
        try:
            save_cache(merged)
        except Exception:
            _log.warning("Episodios que faltan: no se pudo guardar el mirror local tras sincronizar",
                         exc_info=True)
            return
        # Igual que _apply_synced_favorites: si el merge no trajo nada
        # nuevo de verdad, no repintar la tabla entera solo porque la
        # sincronización se disparó -- eso es lo que se veía como "se
        # recarga 2-3 veces" al entrar en la pestaña (favoritos/veredictos/
        # episodios completan cada uno en su propio momento).
        if changed and getattr(self, "_missing_ep_visible", False):
            self._missing_ep_results = self._load_missing_episodes_from_cache()
            self._invalidate_missing_ep_complete_rows()   # la caché en disco acaba de cambiar
            self._render_missing_episodes_table(reset_page=False)
            self._update_missing_ep_status_text()

    _MISSING_EPISODES_SYNC_MIN_INTERVAL = 20   # segundos, ver _sync_missing_episodes_from_ftp

    def _sync_missing_episodes_from_ftp(self):
        """Refresca el mirror local de "Episodios que faltan" desde el
        FTP en segundo plano -- mismo patrón y mismo freno que
        _sync_upload_stats_from_ftp. Se llama al entrar en Episodios que
        faltan, justo antes de que el usuario pueda pulsar "Comprobar"/
        "Reescaneo completo" -- así, un escaneo local siempre parte de la
        base más reciente posible, sin arriesgarse a pisar con un
        resultado desactualizado lo que ya hubiera compartido otro
        cliente para una serie que este escaneo no llegue a tocar."""
        now = _time.time()
        if now - self._last_missing_episodes_sync_ts < self._MISSING_EPISODES_SYNC_MIN_INTERVAL:
            return
        self._last_missing_episodes_sync_ts = now

        remote_path = self._missing_episodes_remote_path()
        if not remote_path:
            return

        def worker():
            import json as _json
            own_ftp = self._new_ftp_client()
            try:
                ok, _msg = own_ftp.connect(
                    self.config_data.get("ftp_host", ""),
                    int(self.config_data.get("ftp_port", 21)),
                    self.config_data.get("ftp_user", ""),
                    self.config_data.get("ftp_password", ""),
                    self.config_data.get("ftp_use_tls", False))
                if not ok:
                    return
                raw = own_ftp.download_bytes(remote_path)
                if raw is None:
                    return
                try:
                    remote_cache = _json.loads(raw.decode("utf-8"))
                except ValueError:
                    return
                if not isinstance(remote_cache, dict):
                    return
                self.after(0, lambda: self._apply_synced_missing_episodes(remote_cache))
            finally:
                own_ftp.disconnect()
        threading.Thread(target=worker, daemon=True).start()

    _MISSING_MOVIES_SYNC_MIN_INTERVAL = 20   # segundos, ver _sync_missing_movies_from_ftp

    def _apply_synced_missing_movies(self, remote_cache: dict):
        """Aplica una caché de "Películas" ya sincronizada (de
        _sync_missing_movies_from_ftp) -- propaga sobre el mirror local el
        flag "in_server=True" de lo que haya publicado otro cliente del
        mismo servidor (si otro cliente ya subió una película, se marca
        como en servidor aquí también, aunque este Jellyfin/Plex aún no la
        haya reindexado), la guarda, y reconstruye self._movies_results con
        la MISMA función que ya usa el arranque (_rows_from_movies_cache).
        NO añade ni borra entradas (ver apply_remote_in_server): un
        descarte local con 🚫 no debe reaparecer por el solo hecho de que
        otro cliente la tenga compartida. Solo si el merge trajo algo
        nuevo de verdad y la pestaña Películas está visible se repinta la
        tabla."""
        from core.missing_movies_cache import load_cache, save_cache, apply_remote_in_server
        previous = load_cache()
        merged, changed = apply_remote_in_server(previous, remote_cache)
        if not changed:
            return
        try:
            save_cache(merged)
        except Exception:
            _log.warning("Películas: no se pudo guardar el mirror local tras sincronizar",
                         exc_info=True)
            return
        # Refrescar _movies_results SIEMPRE (aunque la pestaña no esté
        # visible ahora): el sync de arranque/volver a la app puede
        # aplicarse antes de que el usuario abra la pestaña, y así al
        # entrar ya muestra el flag en servidor actualizado. El repintado
        # de la tabla sí se condiciona a que la pestaña esté visible.
        self._movies_results = self._rows_from_movies_cache()
        self._refresh_movies_genre_filter_options()
        if getattr(self, "_movies_visible", False):
            self._render_movies_table(reset_page=False)
            self._update_movies_status_text()

